/* The canvas is the whole page: no chrome, no letterboxing, no scrollbars. */

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05060c;
  color: #e8e6f2;
  font-family: "Trebuchet MS", "DejaVu Sans", system-ui, sans-serif;
  overscroll-behavior: none;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#screen {
  display: block;
  width: 100vw;
  height: 100vh;
  /* Fall back to the dynamic viewport unit where it exists, so mobile browser
     chrome sliding away does not leave a gap under the canvas. */
  width: 100dvw;
  height: 100dvh;
  cursor: crosshair;
  background: #05060c;
}

/* Shown only on a very short landscape phone, where the play area gets cramped. */
#rotate-hint {
  position: fixed;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(10, 8, 20, 0.8);
  border: 1px solid rgba(190, 170, 255, 0.25);
  font-size: 13px;
  letter-spacing: 0.02em;
  display: none;
  pointer-events: none;
}

@media (max-height: 420px) and (orientation: landscape) and (pointer: coarse) {
  #rotate-hint { display: block; }
}

/* Procedural art. Every sprite is painted once into an offscreen canvas at boot
   at 2x supersample, then blitted at world size — so shapes stay smooth when
   the camera zooms, and no frame ever pays for path work.

   House style, applied to everything so the cast reads as one world:
     - a dark ink outline, because the world is night-dark;
     - a vertical body gradient, light at the top;
     - a cool moonlight rim along the upper-left edge;
     - one saturated accent (eyes, gems, flame) that is allowed to glow.
*/
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.art = (function () {
  var U = VS.util;
  var SS = 2;                                   // supersample factor
  var sprites = {};

  function canvas(w, h) {
    var c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(w));
    c.height = Math.max(1, Math.round(h));
    return c;
  }

  /* Define a sprite `name` of world size w x h. The draw function works in
     world units; the supersample is handled here. */
  function mk(name, w, h, draw) {
    var c = canvas(w * SS, h * SS);
    var g = c.getContext('2d');
    g.scale(SS, SS);
    g.lineJoin = 'round';
    g.lineCap = 'round';
    draw(g, w, h);
    sprites[name] = { canvas: c, w: w, h: h, flash: null };
    return sprites[name];
  }

  /* White silhouette used for the one-frame hit flash. Built lazily: only
     things that actually get hit ever need one. */
  function flashOf(sp) {
    if (sp.flash) return sp.flash;
    var c = canvas(sp.canvas.width, sp.canvas.height);
    var g = c.getContext('2d');
    g.drawImage(sp.canvas, 0, 0);
    g.globalCompositeOperation = 'source-in';
    g.fillStyle = '#ffffff';
    g.fillRect(0, 0, c.width, c.height);
    sp.flash = c;
    return c;
  }

  /* ---- painting helpers -------------------------------------------------- */
  function grad(g, x0, y0, x1, y1, stops) {
    var gr = g.createLinearGradient(x0, y0, x1, y1);
    for (var i = 0; i < stops.length; i++) gr.addColorStop(stops[i][0], stops[i][1]);
    return gr;
  }

  function radial(g, x, y, r0, r1, stops) {
    var gr = g.createRadialGradient(x, y, r0, x, y, r1);
    for (var i = 0; i < stops.length; i++) gr.addColorStop(stops[i][0], stops[i][1]);
    return gr;
  }

  function path(g, pts, close) {
    g.beginPath();
    g.moveTo(pts[0][0], pts[0][1]);
    for (var i = 1; i < pts.length; i++) {
      var p = pts[i];
      if (p.length === 4) g.quadraticCurveTo(p[0], p[1], p[2], p[3]);
      else g.lineTo(p[0], p[1]);
    }
    if (close !== false) g.closePath();
  }

  function inked(g, drawPath, fill, ink, width) {
    drawPath();
    g.strokeStyle = ink || 'rgba(8,6,16,0.9)';
    g.lineWidth = width || 2;
    g.stroke();
    if (fill) { g.fillStyle = fill; g.fill(); }
  }

  /* Cool light along the top-left edge — the single biggest reason these read
     as sculpted rather than flat. */
  function rim(g, drawPath, color, width) {
    g.save();
    drawPath();
    g.clip();
    g.strokeStyle = color || 'rgba(150,190,255,0.65)';
    g.lineWidth = (width || 3);
    g.translate(-0.9, -1.2);
    drawPath();
    g.stroke();
    g.restore();
  }

  function ellipsePath(g, x, y, rx, ry) {
    return function () { g.beginPath(); g.ellipse(x, y, rx, ry, 0, 0, U.TAU); };
  }

  function eyes(g, x0, x1, y, r, color, glow) {
    g.fillStyle = glow || 'rgba(255,120,80,0.35)';
    g.beginPath(); g.arc(x0, y, r * 2.6, 0, U.TAU); g.fill();
    g.beginPath(); g.arc(x1, y, r * 2.6, 0, U.TAU); g.fill();
    g.fillStyle = color;
    g.beginPath(); g.arc(x0, y, r, 0, U.TAU); g.fill();
    g.beginPath(); g.arc(x1, y, r, 0, U.TAU); g.fill();
  }

  /* ---- the hero ---------------------------------------------------------- */
  /* A hooded hunter: crimson cloak, gold trim, a lantern on the belt. Four walk
     frames; the sprite faces right and is flipped when walking left. */
  function drawHero(g, w, h, frame) {
    var cx = w / 2;
    var bob = [0, -1, 0, 1][frame];
    var stride = [0, 1, 0, -1][frame];

    g.save();
    g.translate(0, bob);

    // legs
    g.strokeStyle = '#2a2233';
    g.lineWidth = 4;
    g.beginPath();
    g.moveTo(cx - 3, h - 9); g.lineTo(cx - 3 - stride * 2.5, h - 2);
    g.moveTo(cx + 3, h - 9); g.lineTo(cx + 3 + stride * 2.5, h - 2);
    g.stroke();
    g.strokeStyle = '#171320';
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(cx - 3 - stride * 2.5, h - 2.5); g.lineTo(cx - 1 - stride * 2.5, h - 2.5);
    g.moveTo(cx + 3 + stride * 2.5, h - 2.5); g.lineTo(cx + 5 + stride * 2.5, h - 2.5);
    g.stroke();

    // cloak
    var cloak = function () {
      path(g, [
        [cx - 9, h - 6], [cx - 10, h - 16, cx - 7, h - 24],
        [cx, h - 27], [cx + 7, h - 24], [cx + 10, h - 16, cx + 9, h - 6],
        [cx + 5, h - 8], [cx, h - 6], [cx - 5, h - 8]
      ]);
    };
    inked(g, cloak, grad(g, cx - 8, h - 26, cx + 8, h - 4, [
      [0, '#a3243a'], [0.55, '#7d1a2e'], [1, '#4a0f1e']
    ]));
    rim(g, cloak, 'rgba(160,200,255,0.5)', 2.4);

    // gold trim
    g.strokeStyle = '#e8b45a';
    g.lineWidth = 1.2;
    g.beginPath();
    g.moveTo(cx - 7.5, h - 9); g.quadraticCurveTo(cx, h - 6.5, cx + 7.5, h - 9);
    g.stroke();

    // hood + face shadow
    var hood = function () {
      path(g, [
        [cx - 8, h - 22], [cx - 9, h - 31, cx, h - 33],
        [cx + 9, h - 31, cx + 8, h - 22], [cx + 4, h - 20], [cx - 4, h - 20]
      ]);
    };
    inked(g, hood, grad(g, cx - 6, h - 33, cx + 6, h - 20, [
      [0, '#5d2233'], [1, '#33101d']
    ]));
    rim(g, hood, 'rgba(170,205,255,0.55)', 2.2);

    g.fillStyle = '#160d16';
    g.beginPath();
    g.ellipse(cx + 0.5, h - 25, 4.6, 4.0, 0, 0, U.TAU);
    g.fill();
    eyes(g, cx - 1, cx + 2.6, h - 25, 0.9, '#ffe9a8', 'rgba(255,200,110,0.4)');

    // lantern at the hip, the in-world source of the torchlight around you
    g.fillStyle = 'rgba(255,190,90,0.35)';
    g.beginPath(); g.arc(cx + 8.5, h - 13, 4.5, 0, U.TAU); g.fill();
    g.fillStyle = '#ffd27a';
    g.beginPath(); g.arc(cx + 8.5, h - 13, 1.9, 0, U.TAU); g.fill();
    g.strokeStyle = '#3a2a18';
    g.lineWidth = 1;
    g.beginPath(); g.arc(cx + 8.5, h - 13, 2.8, 0, U.TAU); g.stroke();

    g.restore();
  }

  /* ---- enemies ----------------------------------------------------------- */
  function drawBat(g, w, h, frame) {
    var cx = w / 2, cy = h / 2 + 1;
    var flap = frame === 0 ? -3.5 : 2.5;
    var wing = function () {
      path(g, [
        [cx - 2, cy], [cx - 7, cy - 4 + flap, cx - 10, cy + flap],
        [cx - 6, cy + 2.5], [cx - 8, cy + 4.5], [cx - 3, cy + 3]
      ]);
    };
    var wing2 = function () {
      path(g, [
        [cx + 2, cy], [cx + 7, cy - 4 + flap, cx + 10, cy + flap],
        [cx + 6, cy + 2.5], [cx + 8, cy + 4.5], [cx + 3, cy + 3]
      ]);
    };
    var fill = grad(g, cx, cy - 6, cx, cy + 6, [[0, '#6a4a86'], [1, '#33203f']]);
    inked(g, wing, fill, 'rgba(10,6,18,0.9)', 1.6);
    inked(g, wing2, fill, 'rgba(10,6,18,0.9)', 1.6);
    rim(g, wing, 'rgba(170,150,255,0.5)', 1.6);
    rim(g, wing2, 'rgba(170,150,255,0.5)', 1.6);

    var body = ellipsePath(g, cx, cy + 0.5, 3.6, 4.4);
    inked(g, body, grad(g, cx, cy - 4, cx, cy + 5, [[0, '#7d5a99'], [1, '#3a2547']]), 'rgba(10,6,18,0.9)', 1.6);
    // ears
    g.fillStyle = '#5b3f72';
    g.beginPath();
    g.moveTo(cx - 3, cy - 3.4); g.lineTo(cx - 1.6, cy - 6.4); g.lineTo(cx - 0.4, cy - 3.6); g.closePath(); g.fill();
    g.beginPath();
    g.moveTo(cx + 3, cy - 3.4); g.lineTo(cx + 1.6, cy - 6.4); g.lineTo(cx + 0.4, cy - 3.6); g.closePath(); g.fill();
    eyes(g, cx - 1.5, cx + 1.5, cy - 0.6, 0.85, '#ff6a5a', 'rgba(255,80,70,0.35)');
    g.fillStyle = '#ffffff';
    g.fillRect(cx - 1.4, cy + 2.2, 0.8, 1.6);
    g.fillRect(cx + 0.7, cy + 2.2, 0.8, 1.6);
  }

  function drawZombie(g, w, h, frame) {
    var cx = w / 2;
    var bob = frame === 0 ? 0 : -1;
    var swing = frame === 0 ? 1 : -1;
    g.save();
    g.translate(0, bob);

    // outstretched arms
    g.strokeStyle = '#4e6b3f';
    g.lineWidth = 3.4;
    g.beginPath();
    g.moveTo(cx - 5, h - 19); g.lineTo(cx - 10, h - 17 + swing);
    g.moveTo(cx + 5, h - 19); g.lineTo(cx + 10, h - 17 - swing);
    g.stroke();
    g.strokeStyle = 'rgba(10,14,8,0.85)';
    g.lineWidth = 1;
    g.stroke();

    // legs
    g.strokeStyle = '#3c4f33';
    g.lineWidth = 4;
    g.beginPath();
    g.moveTo(cx - 3, h - 9); g.lineTo(cx - 4 - swing, h - 2);
    g.moveTo(cx + 3, h - 9); g.lineTo(cx + 4 + swing, h - 2);
    g.stroke();

    var torso = function () {
      path(g, [
        [cx - 6, h - 8], [cx - 7, h - 18, cx - 4, h - 21],
        [cx + 4, h - 21], [cx + 7, h - 18, cx + 6, h - 8], [cx, h - 6]
      ]);
    };
    inked(g, torso, grad(g, cx, h - 22, cx, h - 6, [[0, '#6d8a55'], [1, '#354426']]));
    rim(g, torso, 'rgba(150,200,255,0.45)', 2.2);
    // torn shirt
    g.fillStyle = 'rgba(30,40,24,0.55)';
    g.fillRect(cx - 5, h - 14, 10, 3);

    var head = ellipsePath(g, cx, h - 25, 5, 5.2);
    inked(g, head, grad(g, cx - 3, h - 30, cx + 3, h - 20, [[0, '#8aa96c'], [1, '#4a5f38']]));
    rim(g, head, 'rgba(160,205,255,0.5)', 2);
    eyes(g, cx - 1.9, cx + 1.9, h - 26, 0.9, '#d9ff7a', 'rgba(180,255,110,0.28)');
    g.strokeStyle = '#2c3a20';
    g.lineWidth = 1;
    g.beginPath(); g.moveTo(cx - 2, h - 22.5); g.lineTo(cx + 2, h - 22.5); g.stroke();
    g.restore();
  }

  function drawSkeleton(g, w, h, frame) {
    var cx = w / 2;
    var swing = frame === 0 ? 1 : -1;
    var bone = grad(g, cx, h - 30, cx, h - 4, [[0, '#f0ead6'], [1, '#9d9682']]);

    g.strokeStyle = '#cfc8b4';
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(cx - 3, h - 9); g.lineTo(cx - 4 - swing, h - 2);
    g.moveTo(cx + 3, h - 9); g.lineTo(cx + 4 + swing, h - 2);
    g.moveTo(cx - 5, h - 20); g.lineTo(cx - 9, h - 14 + swing);
    g.moveTo(cx + 5, h - 20); g.lineTo(cx + 9, h - 14 - swing);
    g.stroke();

    var ribs = function () {
      path(g, [[cx - 5, h - 10], [cx - 6, h - 20, cx, h - 22], [cx + 6, h - 20, cx + 5, h - 10], [cx, h - 8]]);
    };
    inked(g, ribs, bone);
    rim(g, ribs, 'rgba(180,215,255,0.6)', 2);
    g.strokeStyle = 'rgba(90,84,70,0.8)';
    g.lineWidth = 1;
    for (var i = 0; i < 3; i++) {
      g.beginPath();
      g.moveTo(cx - 4.2, h - 18 + i * 3.2);
      g.quadraticCurveTo(cx, h - 16.4 + i * 3.2, cx + 4.2, h - 18 + i * 3.2);
      g.stroke();
    }

    var skull = function () {
      path(g, [
        [cx - 4.6, h - 24], [cx - 4.8, h - 31, cx, h - 31.5],
        [cx + 4.8, h - 31, cx + 4.6, h - 24], [cx + 2.4, h - 22.4], [cx - 2.4, h - 22.4]
      ]);
    };
    inked(g, skull, bone);
    rim(g, skull, 'rgba(190,220,255,0.65)', 2);
    eyes(g, cx - 1.9, cx + 1.9, h - 26.5, 1.05, '#5ce1ff', 'rgba(80,210,255,0.35)');
    g.fillStyle = '#3a352c';
    g.fillRect(cx - 1.6, h - 23.6, 3.2, 1.2);
  }

  function drawSlime(g, w, h, frame) {
    var cx = w / 2, base = h - 2;
    var squash = frame === 0 ? 1 : 0.86;
    var rx = 9.5 / squash, ry = 8.5 * squash;
    var body = function () {
      g.beginPath();
      g.moveTo(cx - rx, base);
      g.quadraticCurveTo(cx - rx, base - ry * 2, cx, base - ry * 2);
      g.quadraticCurveTo(cx + rx, base - ry * 2, cx + rx, base);
      g.closePath();
    };
    inked(g, body, grad(g, cx, base - ry * 2, cx, base, [
      [0, 'rgba(150,255,190,0.92)'], [0.6, 'rgba(60,190,130,0.9)'], [1, 'rgba(20,110,80,0.95)']
    ]));
    rim(g, body, 'rgba(200,255,235,0.7)', 2.2);
    // inner highlight blob
    g.fillStyle = 'rgba(230,255,240,0.5)';
    g.beginPath(); g.ellipse(cx - 3, base - ry * 1.3, 2.6, 1.8, -0.4, 0, U.TAU); g.fill();
    eyes(g, cx - 2.6, cx + 2.6, base - ry, 1.1, '#0f2a20', 'rgba(0,0,0,0.12)');
    g.fillStyle = '#ffffff';
    g.beginPath(); g.arc(cx - 3, base - ry - 0.5, 0.5, 0, U.TAU); g.fill();
    g.beginPath(); g.arc(cx + 2.2, base - ry - 0.5, 0.5, 0, U.TAU); g.fill();
  }

  function drawGhost(g, w, h, frame) {
    var cx = w / 2;
    var wob = frame === 0 ? 1 : -1;
    var body = function () {
      g.beginPath();
      g.moveTo(cx - 8, h - 10);
      g.quadraticCurveTo(cx - 9, h - 26, cx, h - 27);
      g.quadraticCurveTo(cx + 9, h - 26, cx + 8, h - 10);
      // tattered hem
      g.quadraticCurveTo(cx + 6, h - 4 + wob, cx + 4, h - 8);
      g.quadraticCurveTo(cx + 2, h - 3 - wob, cx, h - 8);
      g.quadraticCurveTo(cx - 2, h - 3 + wob, cx - 4, h - 8);
      g.quadraticCurveTo(cx - 6, h - 4 - wob, cx - 8, h - 10);
      g.closePath();
    };
    inked(g, body, grad(g, cx, h - 28, cx, h - 4, [
      [0, 'rgba(220,240,255,0.85)'], [0.6, 'rgba(150,180,235,0.6)'], [1, 'rgba(110,140,210,0.25)']
    ]), 'rgba(40,60,110,0.55)', 1.6);
    rim(g, body, 'rgba(255,255,255,0.75)', 2);
    eyes(g, cx - 2.6, cx + 2.6, h - 20, 1.2, '#1b2a5c', 'rgba(90,140,255,0.3)');
  }

  function drawWraith(g, w, h, frame) {
    var cx = w / 2;
    var wob = frame === 0 ? 0 : 1.4;
    g.save();
    g.translate(0, -wob);
    var cloak = function () {
      g.beginPath();
      g.moveTo(cx - 10, h - 4);
      g.quadraticCurveTo(cx - 11, h - 24, cx - 4, h - 30);
      g.lineTo(cx + 4, h - 30);
      g.quadraticCurveTo(cx + 11, h - 24, cx + 10, h - 4);
      g.quadraticCurveTo(cx + 5, h - 8, cx, h - 3);
      g.quadraticCurveTo(cx - 5, h - 8, cx - 10, h - 4);
      g.closePath();
    };
    inked(g, cloak, grad(g, cx, h - 32, cx, h - 2, [[0, '#3d2f66'], [0.6, '#241c42'], [1, '#120e26']]));
    rim(g, cloak, 'rgba(170,140,255,0.6)', 2.4);
    // hood hollow
    g.fillStyle = '#0a0714';
    g.beginPath(); g.ellipse(cx, h - 24, 5, 5.6, 0, 0, U.TAU); g.fill();
    eyes(g, cx - 2, cx + 2, h - 24, 1.15, '#ff4d6a', 'rgba(255,60,90,0.4)');
    // scythe
    g.strokeStyle = '#4a3a2a';
    g.lineWidth = 1.6;
    g.beginPath(); g.moveTo(cx + 9, h - 30); g.lineTo(cx + 12, h - 6); g.stroke();
    g.strokeStyle = '#c9d6e6';
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(cx + 9, h - 30);
    g.quadraticCurveTo(cx + 2, h - 34, cx + 1, h - 27);
    g.stroke();
    g.restore();
  }

  function drawBrute(g, w, h, frame) {
    var cx = w / 2;
    var swing = frame === 0 ? 1.5 : -1.5;
    g.strokeStyle = '#5a2f2a';
    g.lineWidth = 7;
    g.beginPath();
    g.moveTo(cx - 6, h - 14); g.lineTo(cx - 8 - swing, h - 3);
    g.moveTo(cx + 6, h - 14); g.lineTo(cx + 8 + swing, h - 3);
    g.stroke();

    var torso = function () {
      path(g, [
        [cx - 13, h - 12], [cx - 15, h - 30, cx - 7, h - 34],
        [cx + 7, h - 34], [cx + 15, h - 30, cx + 13, h - 12], [cx, h - 9]
      ]);
    };
    inked(g, torso, grad(g, cx, h - 36, cx, h - 8, [[0, '#a8493a'], [0.6, '#7b3128'], [1, '#3f1a16']]), 'rgba(10,4,8,0.9)', 2.6);
    rim(g, torso, 'rgba(255,170,150,0.4)', 3);

    // arms + club
    g.strokeStyle = '#933f33';
    g.lineWidth = 6;
    g.beginPath();
    g.moveTo(cx - 11, h - 28); g.lineTo(cx - 17, h - 18 + swing);
    g.moveTo(cx + 11, h - 28); g.lineTo(cx + 17, h - 20 - swing);
    g.stroke();
    g.save();
    g.translate(cx + 17, h - 20 - swing);
    g.rotate(-0.5 + swing * 0.12);
    g.fillStyle = '#5b4326';
    g.fillRect(-2, -16, 4, 18);
    g.fillStyle = '#7a5c33';
    g.beginPath(); g.ellipse(0, -18, 6, 7, 0, 0, U.TAU); g.fill();
    g.strokeStyle = 'rgba(10,6,4,0.8)';
    g.lineWidth = 1.4;
    g.stroke();
    g.restore();

    var head = ellipsePath(g, cx, h - 39, 8, 7.4);
    inked(g, head, grad(g, cx - 4, h - 46, cx + 4, h - 32, [[0, '#c15a45'], [1, '#6d2a22']]), 'rgba(10,4,8,0.9)', 2.4);
    rim(g, head, 'rgba(255,190,170,0.5)', 2.4);
    eyes(g, cx - 3, cx + 3, h - 40, 1.4, '#ffd25a', 'rgba(255,190,80,0.4)');
    // tusks
    g.fillStyle = '#efe6cf';
    g.beginPath(); g.moveTo(cx - 3.5, h - 35); g.lineTo(cx - 2.2, h - 31); g.lineTo(cx - 1, h - 35); g.fill();
    g.beginPath(); g.moveTo(cx + 3.5, h - 35); g.lineTo(cx + 2.2, h - 31); g.lineTo(cx + 1, h - 35); g.fill();
  }

  /* The boss: a crowned skeleton king, drawn big and lit hot so it never gets
     lost in the horde it arrives with. */
  function drawKing(g, w, h, frame) {
    var cx = w / 2;
    var bob = frame === 0 ? 0 : -2;
    g.save();
    g.translate(0, bob);

    // cape
    var cape = function () {
      g.beginPath();
      g.moveTo(cx - 30, h - 14);
      g.quadraticCurveTo(cx - 40, h - 60, cx - 18, h - 78);
      g.lineTo(cx + 18, h - 78);
      g.quadraticCurveTo(cx + 40, h - 60, cx + 30, h - 14);
      g.quadraticCurveTo(cx, h - 26, cx - 30, h - 14);
      g.closePath();
    };
    inked(g, cape, grad(g, cx, h - 80, cx, h - 12, [[0, '#5a1030'], [0.6, '#3a0a20'], [1, '#1a0410']]), 'rgba(8,2,8,0.9)', 3);
    rim(g, cape, 'rgba(255,120,170,0.35)', 3.5);

    // legs
    g.strokeStyle = '#d8d0ba';
    g.lineWidth = 6;
    g.beginPath();
    g.moveTo(cx - 9, h - 26); g.lineTo(cx - 11, h - 4);
    g.moveTo(cx + 9, h - 26); g.lineTo(cx + 11, h - 4);
    g.stroke();

    // ribcage
    var ribs = function () {
      path(g, [
        [cx - 16, h - 28], [cx - 19, h - 56, cx, h - 60], [cx + 19, h - 56, cx + 16, h - 28], [cx, h - 24]
      ]);
    };
    inked(g, ribs, grad(g, cx, h - 62, cx, h - 24, [[0, '#f3ecd8'], [1, '#8d8672']]), 'rgba(8,2,8,0.9)', 2.6);
    rim(g, ribs, 'rgba(190,220,255,0.6)', 3);
    g.strokeStyle = 'rgba(80,74,60,0.85)';
    g.lineWidth = 1.6;
    for (var i = 0; i < 4; i++) {
      g.beginPath();
      g.moveTo(cx - 13, h - 52 + i * 6);
      g.quadraticCurveTo(cx, h - 47 + i * 6, cx + 13, h - 52 + i * 6);
      g.stroke();
    }
    // heart-fire in the ribcage
    g.fillStyle = 'rgba(255,90,60,0.5)';
    g.beginPath(); g.arc(cx, h - 42, 7, 0, U.TAU); g.fill();
    g.fillStyle = '#ffd27a';
    g.beginPath(); g.arc(cx, h - 42, 3, 0, U.TAU); g.fill();

    // arms + great scythe
    g.strokeStyle = '#e2dac4';
    g.lineWidth = 5;
    g.beginPath();
    g.moveTo(cx - 16, h - 54); g.lineTo(cx - 28, h - 38);
    g.moveTo(cx + 16, h - 54); g.lineTo(cx + 28, h - 40);
    g.stroke();
    g.save();
    g.translate(cx + 28, h - 40);
    g.rotate(frame === 0 ? -0.18 : -0.06);
    g.strokeStyle = '#4c3a26';
    g.lineWidth = 3.5;
    g.beginPath(); g.moveTo(0, 26); g.lineTo(2, -40); g.stroke();
    g.strokeStyle = '#dfe9f6';
    g.lineWidth = 5;
    g.beginPath();
    g.moveTo(2, -40);
    g.quadraticCurveTo(-22, -52, -30, -32);
    g.stroke();
    g.strokeStyle = 'rgba(120,220,255,0.6)';
    g.lineWidth = 1.6;
    g.stroke();
    g.restore();

    // skull
    var skull = function () {
      path(g, [
        [cx - 12, h - 62], [cx - 13, h - 80, cx, h - 81],
        [cx + 13, h - 80, cx + 12, h - 62], [cx + 6, h - 59], [cx - 6, h - 59]
      ]);
    };
    inked(g, skull, grad(g, cx, h - 82, cx, h - 58, [[0, '#f7f1de'], [1, '#a49c86']]), 'rgba(8,2,8,0.9)', 2.6);
    rim(g, skull, 'rgba(200,230,255,0.7)', 3);
    eyes(g, cx - 5, cx + 5, h - 70, 2.6, '#ff5a3c', 'rgba(255,90,50,0.45)');
    g.fillStyle = '#2e2a22';
    g.fillRect(cx - 4, h - 62.5, 8, 2.4);
    for (var t = 0; t < 4; t++) g.fillRect(cx - 4 + t * 2.4, h - 62.5, 0.9, 3.4);

    // crown
    g.fillStyle = '#e8b45a';
    g.beginPath();
    g.moveTo(cx - 13, h - 78);
    g.lineTo(cx - 13, h - 86); g.lineTo(cx - 8, h - 81); g.lineTo(cx - 4, h - 89);
    g.lineTo(cx, h - 82); g.lineTo(cx + 4, h - 89); g.lineTo(cx + 8, h - 81);
    g.lineTo(cx + 13, h - 86); g.lineTo(cx + 13, h - 78);
    g.closePath();
    g.fill();
    g.strokeStyle = 'rgba(90,60,20,0.9)';
    g.lineWidth = 1.4;
    g.stroke();
    g.fillStyle = '#ff5a7a';
    g.beginPath(); g.arc(cx, h - 79.5, 1.8, 0, U.TAU); g.fill();

    g.restore();
  }

  /* ---- pickups ----------------------------------------------------------- */
  function drawGem(g, w, h, tint, glow) {
    var cx = w / 2, cy = h / 2;
    g.fillStyle = radial(g, cx, cy, 1, w * 0.75, [[0, glow], [1, 'rgba(0,0,0,0)']]);
    g.fillRect(0, 0, w, h);
    var facet = function () {
      g.beginPath();
      g.moveTo(cx, cy - 5.2);
      g.lineTo(cx + 3.8, cy - 1.4);
      g.lineTo(cx, cy + 5.4);
      g.lineTo(cx - 3.8, cy - 1.4);
      g.closePath();
    };
    inked(g, facet, grad(g, cx - 3, cy - 5, cx + 3, cy + 5, [[0, tint[0]], [1, tint[1]]]), 'rgba(6,10,20,0.8)', 1.2);
    g.fillStyle = 'rgba(255,255,255,0.75)';
    g.beginPath();
    g.moveTo(cx, cy - 4.4); g.lineTo(cx + 2.2, cy - 1.6); g.lineTo(cx, cy + 0.4); g.closePath();
    g.fill();
  }

  function drawHeart(g, w, h) {
    var cx = w / 2, cy = h / 2 + 1;
    var heart = function () {
      g.beginPath();
      g.moveTo(cx, cy + 5);
      g.quadraticCurveTo(cx - 8, cy - 1, cx - 4, cy - 5);
      g.quadraticCurveTo(cx - 1, cy - 7, cx, cy - 3.4);
      g.quadraticCurveTo(cx + 1, cy - 7, cx + 4, cy - 5);
      g.quadraticCurveTo(cx + 8, cy - 1, cx, cy + 5);
      g.closePath();
    };
    inked(g, heart, grad(g, cx, cy - 6, cx, cy + 5, [[0, '#ff7b96'], [1, '#b01f3c']]), 'rgba(40,4,12,0.85)', 1.4);
    g.fillStyle = 'rgba(255,255,255,0.65)';
    g.beginPath(); g.ellipse(cx - 2.2, cy - 3, 1.2, 0.9, -0.5, 0, U.TAU); g.fill();
  }

  function drawChest(g, w, h) {
    var cx = w / 2;
    g.fillStyle = radial(g, cx, h / 2, 2, w * 0.7, [[0, 'rgba(255,210,120,0.45)'], [1, 'rgba(255,180,80,0)']]);
    g.fillRect(0, 0, w, h);
    var box = function () { g.beginPath(); g.rect(cx - 10, h - 13, 20, 11); };
    inked(g, box, grad(g, cx, h - 13, cx, h - 2, [[0, '#8a5a2e'], [1, '#4c2f16']]), 'rgba(20,10,4,0.9)', 1.8);
    var lid = function () {
      g.beginPath();
      g.moveTo(cx - 10, h - 13);
      g.quadraticCurveTo(cx, h - 22, cx + 10, h - 13);
      g.closePath();
    };
    inked(g, lid, grad(g, cx, h - 21, cx, h - 13, [[0, '#a56f3a'], [1, '#6b4220']]), 'rgba(20,10,4,0.9)', 1.8);
    g.fillStyle = '#e8b45a';
    g.fillRect(cx - 2.5, h - 15, 5, 6);
    g.strokeStyle = '#f7dda0';
    g.lineWidth = 1.2;
    g.beginPath(); g.moveTo(cx - 10, h - 13); g.lineTo(cx + 10, h - 13); g.stroke();
    g.fillStyle = '#2a1a0c';
    g.beginPath(); g.arc(cx, h - 11.5, 1.1, 0, U.TAU); g.fill();
  }

  function drawMagnet(g, w, h) {
    var cx = w / 2, cy = h / 2;
    g.lineCap = 'butt';
    g.strokeStyle = '#d8dde8';
    g.lineWidth = 4;
    g.beginPath(); g.arc(cx, cy + 1, 5, Math.PI, 0); g.stroke();
    g.strokeStyle = 'rgba(10,14,24,0.85)';
    g.lineWidth = 1;
    g.beginPath(); g.arc(cx, cy + 1, 5, Math.PI, 0); g.stroke();
    g.fillStyle = '#ff5a6a';
    g.fillRect(cx - 7, cy + 1, 4, 4);
    g.fillRect(cx + 3, cy + 1, 4, 4);
    g.fillStyle = '#9fe8ff';
    g.fillRect(cx - 7, cy + 5, 4, 2);
    g.fillRect(cx + 3, cy + 5, 4, 2);
  }

  /* ---- scenery ----------------------------------------------------------- */
  function drawGrave(g, w, h, variant) {
    var cx = w / 2;
    var stone = grad(g, cx - 6, h - 24, cx + 8, h - 2, [[0, '#8e93a6'], [0.5, '#5f6577'], [1, '#3a3f4d']]);
    var shape = function () {
      if (variant === 0) {
        g.beginPath();
        g.moveTo(cx - 8, h - 2);
        g.lineTo(cx - 8, h - 16);
        g.quadraticCurveTo(cx, h - 26, cx + 8, h - 16);
        g.lineTo(cx + 8, h - 2);
        g.closePath();
      } else if (variant === 1) {
        g.beginPath();
        g.rect(cx - 3, h - 24, 6, 22);
        g.rect(cx - 9, h - 19, 18, 5);
      } else {
        g.beginPath();
        g.moveTo(cx - 7, h - 2);
        g.lineTo(cx - 6, h - 15);
        g.lineTo(cx + 1, h - 20);
        g.lineTo(cx + 7, h - 12);
        g.lineTo(cx + 7, h - 2);
        g.closePath();
      }
    };
    inked(g, shape, stone, 'rgba(6,8,16,0.85)', 2);
    rim(g, shape, 'rgba(150,190,255,0.5)', 2);
    g.strokeStyle = 'rgba(20,24,34,0.6)';
    g.lineWidth = 1;
    if (variant === 0) {
      g.beginPath(); g.moveTo(cx - 4, h - 14); g.lineTo(cx + 4, h - 14); g.stroke();
      g.beginPath(); g.moveTo(cx - 4, h - 11); g.lineTo(cx + 2, h - 11); g.stroke();
    }
    // grass tuft at the base
    g.strokeStyle = 'rgba(60,90,60,0.8)';
    g.lineWidth = 1.2;
    for (var i = -2; i <= 2; i++) {
      g.beginPath();
      g.moveTo(cx + i * 3.5, h - 1.5);
      g.lineTo(cx + i * 3.5 + (i % 2 ? 1.5 : -1.5), h - 5);
      g.stroke();
    }
  }

  function drawDeadTree(g, w, h) {
    var cx = w / 2;
    g.strokeStyle = '#2f2620';
    g.lineCap = 'round';
    g.lineWidth = 6;
    g.beginPath();
    g.moveTo(cx, h - 2);
    g.quadraticCurveTo(cx - 3, h - 22, cx + 2, h - 34);
    g.stroke();
    g.lineWidth = 3.4;
    var branches = [
      [cx + 2, h - 30, cx - 10, h - 36, cx - 16, h - 48],
      [cx + 2, h - 32, cx + 12, h - 40, cx + 17, h - 50],
      [cx + 2, h - 34, cx + 1, h - 46, cx - 5, h - 55],
      [cx + 2, h - 34, cx + 8, h - 48, cx + 7, h - 57]
    ];
    for (var i = 0; i < branches.length; i++) {
      var b = branches[i];
      g.beginPath();
      g.moveTo(b[0], b[1]);
      g.quadraticCurveTo(b[2], b[3], b[4], b[5]);
      g.stroke();
    }
    g.strokeStyle = 'rgba(140,175,235,0.32)';
    g.lineWidth = 1.2;
    for (i = 0; i < branches.length; i++) {
      var b2 = branches[i];
      g.beginPath();
      g.moveTo(b2[0] - 1, b2[1] - 1);
      g.quadraticCurveTo(b2[2] - 1, b2[3] - 1, b2[4] - 1, b2[5] - 1);
      g.stroke();
    }
  }

  function drawRock(g, w, h) {
    var cx = w / 2;
    var shape = function () {
      g.beginPath();
      g.moveTo(cx - 12, h - 2);
      g.lineTo(cx - 9, h - 12);
      g.lineTo(cx - 1, h - 17);
      g.lineTo(cx + 8, h - 13);
      g.lineTo(cx + 12, h - 2);
      g.closePath();
    };
    inked(g, shape, grad(g, cx - 8, h - 18, cx + 8, h - 2, [[0, '#6b6f7e'], [1, '#33363f']]), 'rgba(6,8,16,0.85)', 2);
    rim(g, shape, 'rgba(160,195,255,0.45)', 2);
    g.strokeStyle = 'rgba(20,22,30,0.5)';
    g.lineWidth = 1;
    g.beginPath(); g.moveTo(cx - 4, h - 14); g.lineTo(cx - 1, h - 6); g.stroke();
  }

  function drawTorchPost(g, w, h) {
    var cx = w / 2;
    g.strokeStyle = '#3b2c1c';
    g.lineWidth = 4;
    g.beginPath(); g.moveTo(cx, h - 2); g.lineTo(cx, h - 26); g.stroke();
    g.strokeStyle = 'rgba(160,190,240,0.3)';
    g.lineWidth = 1.2;
    g.beginPath(); g.moveTo(cx - 1.4, h - 3); g.lineTo(cx - 1.4, h - 25); g.stroke();
    g.fillStyle = '#241a10';
    g.beginPath(); g.ellipse(cx, h - 27, 4, 2.6, 0, 0, U.TAU); g.fill();
  }

  function drawBush(g, w, h) {
    var cx = w / 2;
    var shape = function () {
      g.beginPath();
      g.ellipse(cx - 5, h - 5, 5.5, 4.5, 0, 0, U.TAU);
      g.ellipse(cx + 5, h - 5, 5, 4, 0, 0, U.TAU);
      g.ellipse(cx, h - 8, 6.5, 5.5, 0, 0, U.TAU);
    };
    inked(g, shape, grad(g, cx, h - 14, cx, h - 2, [[0, '#39562f'], [1, '#1c2c18']]), 'rgba(6,10,8,0.8)', 1.6);
    rim(g, shape, 'rgba(150,200,255,0.3)', 1.8);
  }

  function drawRuin(g, w, h) {
    var cx = w / 2;
    var wall = function () {
      g.beginPath();
      g.moveTo(cx - 26, h - 2);
      g.lineTo(cx - 26, h - 22);
      g.lineTo(cx - 14, h - 22);
      g.lineTo(cx - 14, h - 30);
      g.lineTo(cx + 4, h - 30);
      g.lineTo(cx + 4, h - 18);
      g.lineTo(cx + 18, h - 18);
      g.lineTo(cx + 18, h - 26);
      g.lineTo(cx + 26, h - 26);
      g.lineTo(cx + 26, h - 2);
      g.closePath();
    };
    inked(g, wall, grad(g, cx, h - 30, cx, h - 2, [[0, '#5b6070'], [1, '#2b2f3a']]), 'rgba(6,8,16,0.85)', 2);
    rim(g, wall, 'rgba(150,190,255,0.45)', 2);
    g.strokeStyle = 'rgba(18,20,28,0.55)';
    g.lineWidth = 1;
    for (var y = h - 8; y > h - 28; y -= 6) {
      g.beginPath(); g.moveTo(cx - 25, y); g.lineTo(cx + 25, y); g.stroke();
    }
  }

  /* ---- weapon projectiles ------------------------------------------------ */
  function drawBolt(g, w, h) {
    var cx = w / 2, cy = h / 2;
    g.fillStyle = radial(g, cx, cy, 0.5, w / 2, [[0, 'rgba(180,230,255,0.95)'], [0.45, 'rgba(90,170,255,0.6)'], [1, 'rgba(60,120,255,0)']]);
    g.fillRect(0, 0, w, h);
    g.fillStyle = '#ffffff';
    g.beginPath(); g.arc(cx, cy, 2.2, 0, U.TAU); g.fill();
  }

  function drawKnife(g, w, h) {
    var cx = w / 2;
    g.fillStyle = '#3a2a1c';
    g.fillRect(cx - 1.2, h - 6, 2.4, 5);
    var blade = function () {
      g.beginPath();
      g.moveTo(cx, 0.5);
      g.lineTo(cx + 2.4, h - 7);
      g.lineTo(cx - 2.4, h - 7);
      g.closePath();
    };
    inked(g, blade, grad(g, cx - 2, 0, cx + 2, h, [[0, '#ffffff'], [1, '#8f9db3']]), 'rgba(10,14,24,0.8)', 1);
  }

  function drawAxe(g, w, h) {
    var cx = w / 2, cy = h / 2;
    g.strokeStyle = '#5b4326';
    g.lineWidth = 3;
    g.beginPath(); g.moveTo(cx, cy + 9); g.lineTo(cx, cy - 6); g.stroke();
    var head = function () {
      g.beginPath();
      g.moveTo(cx - 1, cy - 9);
      g.quadraticCurveTo(cx + 10, cy - 8, cx + 8, cy + 2);
      g.quadraticCurveTo(cx + 3, cy - 1, cx - 1, cy - 1);
      g.closePath();
      g.moveTo(cx + 1, cy - 9);
      g.quadraticCurveTo(cx - 10, cy - 8, cx - 8, cy + 2);
      g.quadraticCurveTo(cx - 3, cy - 1, cx + 1, cy - 1);
      g.closePath();
    };
    inked(g, head, grad(g, cx, cy - 10, cx, cy + 2, [[0, '#e9f0fa'], [1, '#8593a8']]), 'rgba(10,14,24,0.85)', 1.4);
  }

  function drawFlask(g, w, h) {
    var cx = w / 2, cy = h / 2;
    var body = function () {
      g.beginPath();
      g.moveTo(cx - 2, cy - 6);
      g.lineTo(cx + 2, cy - 6);
      g.lineTo(cx + 2, cy - 3);
      g.quadraticCurveTo(cx + 6.5, cy + 1, cx + 4, cy + 6);
      g.lineTo(cx - 4, cy + 6);
      g.quadraticCurveTo(cx - 6.5, cy + 1, cx - 2, cy - 3);
      g.closePath();
    };
    inked(g, body, 'rgba(190,230,255,0.55)', 'rgba(20,40,70,0.8)', 1.2);
    g.fillStyle = 'rgba(120,220,255,0.85)';
    g.beginPath();
    g.moveTo(cx - 4.6, cy + 1);
    g.quadraticCurveTo(cx, cy + 3, cx + 4.6, cy + 1);
    g.lineTo(cx + 4, cy + 6);
    g.lineTo(cx - 4, cy + 6);
    g.closePath();
    g.fill();
    g.fillStyle = '#6b4a2a';
    g.fillRect(cx - 2.4, cy - 8, 4.8, 2.4);
  }

  function drawRune(g, w, h) {
    var cx = w / 2, cy = h / 2;
    g.fillStyle = radial(g, cx, cy, 1, w / 2, [[0, 'rgba(255,220,150,0.9)'], [0.5, 'rgba(255,170,60,0.45)'], [1, 'rgba(255,140,40,0)']]);
    g.fillRect(0, 0, w, h);
    var tab = function () { g.beginPath(); g.rect(cx - 4, cy - 5.5, 8, 11); };
    inked(g, tab, grad(g, cx, cy - 6, cx, cy + 6, [[0, '#f4e6c8'], [1, '#b89a68']]), 'rgba(40,26,10,0.85)', 1.2);
    g.strokeStyle = '#8a2b3c';
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(cx - 1.6, cy - 3); g.lineTo(cx + 1.6, cy - 3);
    g.moveTo(cx, cy - 3.6); g.lineTo(cx, cy + 3.4);
    g.stroke();
  }

  /* ---- UI icons ---------------------------------------------------------- */
  function iconFrame(g, w, h, hue) {
    g.fillStyle = grad(g, 0, 0, 0, h, [[0, 'rgba(60,52,96,0.95)'], [1, 'rgba(26,22,44,0.95)']]);
    g.beginPath();
    g.roundRect ? g.roundRect(1, 1, w - 2, h - 2, 5) : g.rect(1, 1, w - 2, h - 2);
    g.fill();
    g.strokeStyle = hue;
    g.lineWidth = 1.4;
    g.stroke();
  }

  var ICONS = {
    bolt: function (g, w, h) {
      iconFrame(g, w, h, 'rgba(120,190,255,0.8)');
      var cx = w / 2, cy = h / 2;
      g.fillStyle = radial(g, cx, cy, 1, 9, [[0, '#ffffff'], [0.4, '#7ec8ff'], [1, 'rgba(60,120,255,0)']]);
      g.beginPath(); g.arc(cx, cy, 9, 0, U.TAU); g.fill();
    },
    whip: function (g, w, h) {
      iconFrame(g, w, h, 'rgba(255,170,120,0.8)');
      g.strokeStyle = '#ffd9a8';
      g.lineWidth = 2.2;
      g.beginPath();
      g.moveTo(4, h - 6);
      g.quadraticCurveTo(w / 2, 4, w - 4, h / 2);
      g.stroke();
      g.strokeStyle = 'rgba(255,120,60,0.7)';
      g.lineWidth = 1;
      g.stroke();
    },
    axe: function (g, w, h) { g.save(); iconFrame(g, w, h, 'rgba(200,220,255,0.8)'); g.translate(w / 2 - 11, h / 2 - 11); g.scale(0.9, 0.9); drawAxe(g, 24, 24); g.restore(); },
    aura: function (g, w, h) {
      iconFrame(g, w, h, 'rgba(160,255,190,0.8)');
      var cx = w / 2, cy = h / 2;
      g.fillStyle = radial(g, cx, cy, 2, 11, [[0, 'rgba(180,255,200,0.5)'], [1, 'rgba(80,220,140,0)']]);
      g.beginPath(); g.arc(cx, cy, 11, 0, U.TAU); g.fill();
      g.strokeStyle = 'rgba(190,255,210,0.9)';
      g.lineWidth = 1.4;
      g.beginPath(); g.arc(cx, cy, 8, 0, U.TAU); g.stroke();
      g.fillStyle = '#eaf7e0';
      g.beginPath(); g.ellipse(cx, cy, 3, 4, 0, 0, U.TAU); g.fill();
    },
    water: function (g, w, h) { g.save(); iconFrame(g, w, h, 'rgba(140,220,255,0.8)'); g.translate(w / 2 - 12, h / 2 - 12); drawFlask(g, 24, 24); g.restore(); },
    lightning: function (g, w, h) {
      iconFrame(g, w, h, 'rgba(200,180,255,0.85)');
      g.fillStyle = '#e9dcff';
      g.beginPath();
      g.moveTo(w / 2 + 3, 5); g.lineTo(w / 2 - 5, h / 2 + 1); g.lineTo(w / 2, h / 2 + 1);
      g.lineTo(w / 2 - 3, h - 5); g.lineTo(w / 2 + 6, h / 2 - 2); g.lineTo(w / 2 + 1, h / 2 - 2);
      g.closePath();
      g.fill();
    },
    orbit: function (g, w, h) {
      iconFrame(g, w, h, 'rgba(255,210,140,0.85)');
      var cx = w / 2, cy = h / 2;
      g.strokeStyle = 'rgba(255,220,160,0.55)';
      g.lineWidth = 1.2;
      g.beginPath(); g.ellipse(cx, cy, 9, 5.5, -0.4, 0, U.TAU); g.stroke();
      g.save(); g.translate(cx - 9, cy - 9); g.scale(0.75, 0.75); drawRune(g, 24, 24); g.restore();
    },
    might: function (g, w, h) {
      iconFrame(g, w, h, 'rgba(255,140,140,0.85)');
      g.fillStyle = '#ff9a9a';
