    // Numbers only where they inform: bosses, elites, and an occasional pop on
    // the rank and file, so the screen never becomes a wall of digits.
    if (wasBig || Math.random() < 0.05) {
      VS.particles.number(e.x, e.y - e.r - 8, String(Math.round(dmg)), killed ? '#ffd06b' : '#ffffff', wasBig ? 17 : 13);
    }
    VS.audio.hit();
  }

  function onContact(e) {
    if (P.takeDamage(e.dmg)) {
      data.state = 'dead';
      data.stateT = 0;
      recordBest();
      VS.audio.stopDrone();
    }
    // Push the attacker off so a crowd cannot chain-hit through one frame.
    var dx = e.x - P.state.x, dy = e.y - P.state.y;
    var d = Math.sqrt(dx * dx + dy * dy) || 1;
    e.kx += dx / d * 130;
    e.ky += dy / d * 130;
  }

  function collect(item) {
    var pl = P.state;
    if (item.kind === 'gem') {
      VS.audio.gem();
      P.addXp(item.value, queueLevelUp);
      VS.particles.spark(item.x, item.y, 0, -40, 0.2, 2, 160, 230, 255);
    } else if (item.kind === 'heart') {
      var healed = P.heal(40);
      VS.audio.heal();
      VS.particles.number(pl.x, pl.y - 40, '+' + Math.round(healed), '#8bef98', 16);
    } else if (item.kind === 'magnet') {
      VS.pickups.pullAll();
      VS.audio.chest();
      VS.hud.announce('EVERYTHING COMES TO YOU', '#9fe8ff');
    } else if (item.kind === 'chest') {
      // Chests skip the choice screen and hand out rolls directly — the pace
      // break of a menu would undercut the reward.
      var rolls = 1 + (Math.random() < 0.45 ? 1 : 0) + (Math.random() < 0.2 ? 1 : 0);
      var names = [];
      for (var i = 0; i < rolls; i++) {
        var opt = VS.upgrades.roll(1)[0];
        VS.upgrades.take(opt, pl);
        names.push(opt.name);
      }
      VS.audio.chest();
      VS.particles.flash(pl.x, pl.y, 260, '255,210,130', 0.5, 1);
      VS.hud.announce(names.join('  ·  '), '#ffd9a8');
    }
  }

  function queueLevelUp(levels) {
    data.pendingLevels += levels;
    VS.audio.levelUp();
    // A breathing-room shove: no damage, just space to read the cards.
    E.damageArea(P.state.x, P.state.y, 190, 0, 420, onKill);
    VS.particles.ring(P.state.x, P.state.y, '255,235,170', 900, 0.5, 5);
    VS.particles.flash(P.state.x, P.state.y, 320, '255,220,140', 0.45, 1);
  }

  function openLevelUp() {
    data.options = VS.upgrades.roll(3);

    // Once every weapon and passive is maxed the roll can only return filler.
    // Stopping the game to "choose" between three identical heals is pure
    // friction, so take it silently and keep playing.
    var allFiller = true;
    for (var i = 0; i < data.options.length; i++) {
      if (data.options[i].kind !== 'filler') { allFiller = false; break; }
    }
    if (allFiller) {
      VS.upgrades.take(data.options[0], P.state);
      VS.particles.number(P.state.x, P.state.y - 40, '+40', '#8bef98', 15);
      data.pendingLevels--;
      if (data.pendingLevels > 0) openLevelUp();
      else { data.state = 'playing'; data.stateT = 0; }
      return;
    }

    data.selected = 0;
    VS.screens.layoutCards(data.options);
    data.state = 'levelup';
    data.stateT = 0;
  }

  function chooseOption(index) {
    var opt = data.options[index];
    if (!opt) return;
    VS.upgrades.take(opt, P.state);
    VS.audio.select();
    data.pendingLevels--;
    if (data.pendingLevels > 0) openLevelUp();
    else {
      data.state = 'playing';
      data.stateT = 0;
    }
  }

  function recordBest() {
    if (data.elapsed > data.best) {
      data.best = data.elapsed;
      U.saveJSON('nightharvest.best', Math.floor(data.best));
    }
  }

  /* ---- update ------------------------------------------------------------- */
  function update(dt) {
    data.stateT += dt;
    var input = VS.input;

    if (input.pressed('sound')) VS.audio.toggle();

    if (data.state === 'title') {
      R.follow(P.state.x, P.state.y, dt);
      VS.particles.update(dt);
      if (input.pressed('confirm') || input.pointer.clicked) start();
      return;
    }

    if (data.state === 'dead' || data.state === 'victory') {
      VS.particles.update(dt);
      R.updateShake(dt);
      if (data.stateT > 0.9 && (input.pressed('confirm') || input.pointer.clicked)) {
        resetRun();
        data.state = 'title';
        data.stateT = 0;
        VS.audio.stopDrone();
      }
      return;
    }

    if (data.state === 'levelup') {
      if (input.pressed('pick1')) chooseOption(0);
      else if (input.pressed('pick2')) chooseOption(1);
      else if (input.pressed('pick3')) chooseOption(2);
      else if (input.pressed('left')) { data.selected = (data.selected + 2) % 3; VS.audio.move(); }
      else if (input.pressed('right')) { data.selected = (data.selected + 1) % 3; VS.audio.move(); }
      else if (input.pressed('up')) { data.selected = (data.selected + 2) % 3; VS.audio.move(); }
      else if (input.pressed('down')) { data.selected = (data.selected + 1) % 3; VS.audio.move(); }
      else if (input.pressed('confirm')) chooseOption(data.selected);
      else if (input.pointer.clicked) {
        var hit = VS.screens.hitTest(input.pointer.x, input.pointer.y);
        if (hit >= 0) chooseOption(hit);
      } else if (input.pointer.moved) {
        var hover = VS.screens.hitTest(input.pointer.x, input.pointer.y);
        if (hover >= 0 && hover !== data.selected) { data.selected = hover; VS.audio.move(); }
      }
      VS.particles.update(dt * 0.35);
      return;
    }

    if (input.pressed('pause')) {
      data.state = data.state === 'paused' ? 'playing' : 'paused';
      return;
    }
    if (data.state === 'paused') return;

    /* ---- the run itself ---- */
    data.elapsed += dt;
    var pl = P.state;

    // The camera rect drives spawning, so refresh it before the director runs.
    R.updateView();
    VS.director.update(dt);
    P.update(dt, input, true);
    VS.weapons.update(dt, pl, pl.stats);
    VS.projectiles.update(dt, pl);
    E.update(dt, pl, onContact);
    VS.projectiles.resolve(E.grid, hurtEnemy);
    VS.pickups.update(dt, pl, collect);
    VS.particles.update(dt);
    VS.hud.updateBanner(dt);
    R.follow(pl.x, pl.y, dt);
    R.updateShake(dt);

    // Announce set pieces as they land.
    var ev = VS.director.nextEvent();
    if (ev && ev.t - data.elapsed < 0.05 && ev.t - data.elapsed > -0.05) {
      if (ev.label === 'BOSS' || ev.label === 'FINAL') VS.hud.announce('THE BONE KING RISES', '#ff9aa8');
      else if (ev.label === 'ELITE') VS.hud.announce('SOMETHING STRONGER', '#ffc45a');
    }

    if (data.pendingLevels > 0) openLevelUp();

    if (!pl.alive && data.state === 'playing') {
      data.state = 'dead';
      data.stateT = 0;
      recordBest();
      VS.audio.stopDrone();
    }
  }

  /* ---- draw --------------------------------------------------------------- */
  function drawWorld() {
    var g = R.beginWorld();
    var view = R.view;

    VS.terrain.drawGround(g, view);
    VS.projectiles.drawGround(g);
    VS.pickups.draw(g);

    // Collect everything that needs depth sorting.
    entryCount = 0;
    torchCount = 0;
    VS.terrain.eachProp(view, function (prop) {
      if (prop.x < view.x0 - 80 || prop.x > view.x1 + 80 || prop.y < view.y0 - 100 || prop.y > view.y1 + 80) return;
      pushEntry(prop.y, 'prop', null, prop.x, prop.sprite);
      if (prop.light) {
        var t = torchLights[torchCount];
        if (!t) { t = { x: 0, y: 0 }; torchLights[torchCount] = t; }
        t.x = prop.x; t.y = prop.y - 28;
        torchCount++;
      }
    });
    E.pool.each(function (e) {
      if (!R.visible(e.x, e.y, e.r + 60)) return;
      pushEntry(e.y, 'enemy', e, e.x, '');
    });
    if (P.state.alive) pushEntry(P.state.y, 'player', null, P.state.x, '');

    sortView.length = entryCount;
    sortView.sort(byY);

    for (var i = 0; i < entryCount; i++) {
      var e = sortView[i];
      if (e.kind === 'enemy') E.drawOne(g, e.ref);
      else if (e.kind === 'prop') VS.art.drawFooted(g, e.sprite, e.x, e.y);
      else P.draw(g);
    }

    // Torch flames: drawn after the props so they sit in front of their post.
    for (i = 0; i < torchCount; i++) {
      var t2 = torchLights[i];
      flame(g, t2.x, t2.y);
    }

    VS.projectiles.drawAir(g);
    VS.particles.draw(g);
    VS.hud.healthWorld(g, P.state);
    VS.particles.drawText(g);
    return g;
  }

  var flameT = 0;
  function flame(g, x, y) {
    var f = Math.sin(flameT * 9 + x * 0.05) * 0.5 + 0.5;
    var h = 9 + f * 4;
    g.fillStyle = 'rgba(255,150,50,0.55)';
    g.beginPath();
    g.ellipse(x, y, 4.5, h * 0.6, 0, 0, U.TAU);
    g.fill();
    g.fillStyle = 'rgba(255,220,140,0.9)';
    g.beginPath();
    g.ellipse(x, y + 1, 2.2, h * 0.36, 0, 0, U.TAU);
    g.fill();
    if (Math.random() < 0.14) VS.particles.ember(x, y - 2);
  }

  function drawLights() {
    R.beginLights();
    P.emitLights();
    for (var i = 0; i < torchCount; i++) {
      var t = torchLights[i];
      var flick = 1 + Math.sin(flameT * 11 + t.x) * 0.06;
      R.light(t.x, t.y, 150 * flick, 0.85);
      R.glow(t.x, t.y, 90 * flick, '255,160,60', 0.34);
    }
    E.emitLights();
    VS.projectiles.emitLights();
    VS.pickups.emitLights();
    VS.particles.emitLights();
    R.composite();
  }

  function draw(dt) {
    flameT += dt || 0;
    R.clear();
    drawWorld();
    drawLights();

    var g = R.beginScreen();
    if (data.state === 'title') {
      VS.screens.drawTitle(g, data.stateT, data.best);
    } else {
      VS.hud.draw(g, data);
      if (data.state === 'levelup') VS.screens.drawLevelUp(g, data.options, data.selected, P.state.level);
      else if (data.state === 'paused') VS.screens.drawPause(g);
      else if (data.state === 'dead') VS.screens.drawResult(g, data, false, data.stateT);
      else if (data.state === 'victory') VS.screens.drawResult(g, data, true, data.stateT);
    }

    // Damage vignette, over everything.
    if (P.state.hurtFlash > 0 && data.state !== 'dead') {
      g.save();
      g.globalAlpha = P.state.hurtFlash * 0.6;
      var grd = g.createRadialGradient(R.width / 2, R.height / 2, Math.min(R.width, R.height) * 0.3,
        R.width / 2, R.height / 2, Math.max(R.width, R.height) * 0.62);
      grd.addColorStop(0, 'rgba(255,0,40,0)');
      grd.addColorStop(1, 'rgba(190,0,40,0.85)');
      g.fillStyle = grd;
      g.fillRect(0, 0, R.width, R.height);
      g.restore();
    }
  }

  function onResize() {
    if (data.state === 'levelup') VS.screens.layoutCards(data.options);
  }

  return {
    data: data,
    init: init,
    start: start,
    // Exposed so tools and tests can push damage through the real reward path
    // (xp, drops, boss/victory handling) rather than reaching past it.
    damageEnemy: hurtEnemy,
    update: update,
    draw: draw,
    resetRun: resetRun,
    onResize: onResize,
    chooseOption: chooseOption,
    queueLevelUp: queueLevelUp
  };
})();

/* Input. The player only ever moves — there is no fire button by design — so
   this reduces to a movement vector plus menu confirmation. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.input = (function () {
  var U = VS.util;

  var KEYMAP = {
    ArrowLeft: 'left', KeyA: 'left',
    ArrowRight: 'right', KeyD: 'right',
    ArrowUp: 'up', KeyW: 'up',
    ArrowDown: 'down', KeyS: 'down',
    Enter: 'confirm', NumpadEnter: 'confirm', Space: 'confirm',
    Escape: 'pause', KeyP: 'pause',
    KeyM: 'sound',
    Digit1: 'pick1', Numpad1: 'pick1',
    Digit2: 'pick2', Numpad2: 'pick2',
    Digit3: 'pick3', Numpad3: 'pick3'
  };

  var held = {};
  var pressed = {};
  var canvas = null;

  // Screen-space pointer, in CSS pixels relative to the canvas.
  var pointer = { x: 0, y: 0, down: false, dragging: false, moved: false, clicked: false };
  // Virtual stick: on touch, dragging anywhere steers relative to the touch-down
  // point, which beats an on-screen d-pad for a movement-only game.
  var stick = { active: false, ox: 0, oy: 0, dx: 0, dy: 0 };
  var STICK_RANGE = 70;

  function down(action) {
    if (!held[action]) pressed[action] = true;
    held[action] = true;
  }
  function up(action) { held[action] = false; }

  function onKeyDown(e) {
    var a = KEYMAP[e.code];
    if (!a) return;
    e.preventDefault();
    if (e.repeat) return;
    down(a);
  }
  function onKeyUp(e) {
    var a = KEYMAP[e.code];
    if (!a) return;
    e.preventDefault();
    up(a);
  }

  function toCanvas(e) {
    var r = canvas.getBoundingClientRect();
    pointer.x = e.clientX - r.left;
    pointer.y = e.clientY - r.top;
  }

  function onPointerDown(e) {
    toCanvas(e);
    pointer.down = true;
    pointer.dragging = true;
    pointer.clicked = true;
    stick.active = true;
    stick.ox = pointer.x;
    stick.oy = pointer.y;
    stick.dx = stick.dy = 0;
    if (canvas.setPointerCapture) { try { canvas.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ } }
    e.preventDefault();
  }

  function onPointerMove(e) {
    toCanvas(e);
    pointer.moved = true;
    if (!pointer.dragging) return;
    var dx = pointer.x - stick.ox, dy = pointer.y - stick.oy;
    var d = Math.sqrt(dx * dx + dy * dy);
    if (d > 0) {
      var mag = Math.min(1, d / STICK_RANGE);
      stick.dx = dx / d * mag;
      stick.dy = dy / d * mag;
    }
    // Re-anchor if the finger runs far from the origin, so the stick never
    // saturates in a corner during a long drag.
    if (d > STICK_RANGE * 1.6) {
      stick.ox = pointer.x - stick.dx * STICK_RANGE;
      stick.oy = pointer.y - stick.dy * STICK_RANGE;
    }
    e.preventDefault();
  }

  function onPointerUp(e) {
    pointer.down = false;
    pointer.dragging = false;
    stick.active = false;
    stick.dx = stick.dy = 0;
    e.preventDefault();
  }

  function attach(canvasEl) {
    canvas = canvasEl;
    window.addEventListener('keydown', onKeyDown, { passive: false });
    window.addEventListener('keyup', onKeyUp, { passive: false });
    window.addEventListener('blur', releaseAll);
    canvas.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointermove', onPointerMove, { passive: false });
    window.addEventListener('pointerup', onPointerUp);
    window.addEventListener('pointercancel', onPointerUp);
    canvas.addEventListener('contextmenu', function (e) { e.preventDefault(); });
  }

  function releaseAll() {
    for (var k in held) held[k] = false;
    pointer.down = pointer.dragging = false;
    stick.active = false;
    stick.dx = stick.dy = 0;
  }

  /* The movement vector, normalised, from whichever device is in use. */
  function moveVector(out) {
    var x = 0, y = 0;
    if (held.left) x -= 1;
    if (held.right) x += 1;
    if (held.up) y -= 1;
    if (held.down) y += 1;
    if (x === 0 && y === 0 && stick.active) { x = stick.dx; y = stick.dy; }
    var len = Math.sqrt(x * x + y * y);
    if (len > 1) { x /= len; y /= len; }
    out.x = x;
    out.y = y;
    return out;
  }

  function endStep() {
    pressed = {};
    pointer.clicked = false;
    pointer.moved = false;
  }

  return {
    attach: attach,
    held: function (a) { return !!held[a]; },
    pressed: function (a) { return !!pressed[a]; },
    tap: down,
    release: up,
    pointer: pointer,
    stick: stick,
    stickRange: STICK_RANGE,
    moveVector: moveVector,
    endStep: endStep,
    releaseAll: releaseAll
  };
})();

/* Screen, camera and lighting.

   The canvas always fills the window: the backing store is sized in device
   pixels, the camera keeps a constant world height so a wide monitor simply
   sees more of the field, and everything is drawn in world units.

   Night is done in two extra half-resolution layers:
     shadow  — a sheet of darkness with holes punched out at light sources,
               composited over the world;
     glow    — additive coloured blooms for anything that should feel hot.
   Half resolution is deliberate: the blur it introduces is what makes the
   lights look soft, and it costs a quarter of the fill rate. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.render = (function () {
  var U = VS.util;

  var canvas = null, ctx = null;
  var shadowCanvas = null, shadowCtx = null;
  var glowCanvas = null, glowCtx = null;
  var vignette = null;

  var dpr = 1;
  var cssW = 800, cssH = 600;
  var VIEW_HEIGHT = 700;              // world units visible vertically
  var zoom = 1;
  var LIGHT_SCALE = 0.4;

  var cam = { x: 0, y: 0, shake: 0, shakeX: 0, shakeY: 0 };
  var view = { x0: 0, y0: 0, x1: 0, y1: 0 };

  /* How dark the unlit field is. Tuned by looking at it: at 0.8 the horde
     vanished outside the lantern and the game stopped being playable, so the
     night now only sets a mood and the lantern adds warmth on top. */
  var NIGHT = 'rgba(8,10,26,0.58)';

  function attach(canvasEl) {
    canvas = canvasEl;
    ctx = canvas.getContext('2d', { alpha: false });
    shadowCanvas = VS.art.canvas(2, 2);
    shadowCtx = shadowCanvas.getContext('2d');
    glowCanvas = VS.art.canvas(2, 2);
    glowCtx = glowCanvas.getContext('2d');
    resize();
  }

  function resize() {
    var w = Math.max(320, Math.floor(window.innerWidth || 800));
    var h = Math.max(240, Math.floor(window.innerHeight || 600));
    // Cap the device ratio: a 3x phone screen costs 9x the fill rate for a
    // difference nobody can see through the darkness.
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    cssW = w; cssH = h;
    canvas.width = Math.floor(w * dpr);
    canvas.height = Math.floor(h * dpr);
    canvas.style.width = w + 'px';
    canvas.style.height = h + 'px';

    zoom = U.clamp(h / VIEW_HEIGHT, 0.62, 1.9);
    // Very wide or very short windows would otherwise show an absurd slice of
    // the field; keep the horizontal view within a sane band too.
    var worldW = w / zoom;
    if (worldW > 1900) zoom = w / 1900;
    if (worldW < 620) zoom = w / 620;

    var lw = Math.max(2, Math.floor(w * LIGHT_SCALE));
    var lh = Math.max(2, Math.floor(h * LIGHT_SCALE));
    shadowCanvas.width = lw; shadowCanvas.height = lh;
    glowCanvas.width = lw; glowCanvas.height = lh;

    buildVignette();
    updateView();
    ctx.imageSmoothingEnabled = true;
  }

  function buildVignette() {
    vignette = VS.art.canvas(Math.max(2, Math.floor(cssW * LIGHT_SCALE)), Math.max(2, Math.floor(cssH * LIGHT_SCALE)));
    var g = vignette.getContext('2d');
    var w = vignette.width, h = vignette.height;
    var grd = g.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.28, w / 2, h / 2, Math.max(w, h) * 0.72);
    grd.addColorStop(0, 'rgba(0,0,0,0)');
    grd.addColorStop(0.65, 'rgba(2,3,10,0.16)');
    grd.addColorStop(1, 'rgba(1,2,8,0.5)');
    g.fillStyle = grd;
    g.fillRect(0, 0, w, h);
  }

  function follow(x, y, dt) {
    cam.x = U.damp(cam.x, x, 9, dt);
    cam.y = U.damp(cam.y, y, 9, dt);
  }

  function snapTo(x, y) { cam.x = x; cam.y = y; updateView(); }

  function shake(amount) { cam.shake = Math.max(cam.shake, amount); }

  function updateShake(dt) {
    if (cam.shake > 0) {
      cam.shake = Math.max(0, cam.shake - dt * 2.4);
      var m = cam.shake * 9;
      cam.shakeX = (Math.random() * 2 - 1) * m;
      cam.shakeY = (Math.random() * 2 - 1) * m;
    } else {
      cam.shakeX = cam.shakeY = 0;
    }
  }

  /* Recompute the visible world rectangle.

     The simulation reads `view` too — the spawner puts enemies on a ring just
     outside it — so this must be driven from the update path and not only from
     drawing. (It was drawing-only once, and a headless run with no draw call
     spawned the horde on top of the player.) */
  function updateView() {
    var halfW = cssW / (2 * zoom), halfH = cssH / (2 * zoom);
    view.x0 = cam.x - halfW; view.x1 = cam.x + halfW;
    view.y0 = cam.y - halfH; view.y1 = cam.y + halfH;
    return view;
  }

  /* Begin a world-space pass on the main canvas. */
  function beginWorld() {
    var s = zoom * dpr;
    ctx.setTransform(s, 0, 0, s,
      (cssW / 2 - (cam.x + cam.shakeX) * zoom) * dpr,
      (cssH / 2 - (cam.y + cam.shakeY) * zoom) * dpr);
    updateView();
    return ctx;
  }

  /* Begin a screen-space (CSS pixel) pass for HUD and menus. */
  function beginScreen() {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return ctx;
  }

  function clear() {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#05060c';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }

  /* ---- lighting ---------------------------------------------------------- */
  function beginLights() {
    var g = shadowCtx;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.globalCompositeOperation = 'source-over';
    g.clearRect(0, 0, shadowCanvas.width, shadowCanvas.height);
    g.fillStyle = NIGHT;
    g.fillRect(0, 0, shadowCanvas.width, shadowCanvas.height);
    // World transform at the light layer's reduced scale.
    var s = zoom * LIGHT_SCALE;
    g.setTransform(s, 0, 0, s,
      (cssW / 2 - (cam.x + cam.shakeX) * zoom) * LIGHT_SCALE,
      (cssH / 2 - (cam.y + cam.shakeY) * zoom) * LIGHT_SCALE);
    g.globalCompositeOperation = 'destination-out';

    var g2 = glowCtx;
