        VS.render.glow(it.x, it.y, 70, '255,200,110', 0.45);
      } else if (it.kind === 'heart') {
        VS.render.light(it.x, it.y, 46, 0.6);
        VS.render.glow(it.x, it.y, 34, '255,90,130', 0.35);
      } else {
        VS.render.light(it.x, it.y, 46, 0.6);
        VS.render.glow(it.x, it.y, 34, '160,220,255', 0.35);
