    VS.audio.hurt();
    VS.particles.blood(p.x, p.y - 12, (Math.random() - 0.5), -1, 6);
    VS.particles.number(p.x, p.y - 34, '-' + Math.round(dealt), '#ff8fa3', 16);
    if (p.stats.hp <= 0) {
      if (p.revives > 0) {
        p.revives--;
        p.stats.hp = Math.round(p.stats.maxHp * 0.6);
        p.invuln = 3;
        VS.particles.flash(p.x, p.y, 300, '255,220,255', 0.7, 1);
