  }

  function drawPool(g, p) {
    var t = p.life / p.maxLife;
    var a = Math.min(1, t * 2.2);
    var grd = g.createRadialGradient(p.x, p.y, p.r * 0.15, p.x, p.y, p.r);
    grd.addColorStop(0, 'rgba(150,235,255,' + (0.26 * a) + ')');
    grd.addColorStop(0.7, 'rgba(70,170,255,' + (0.18 * a) + ')');
    grd.addColorStop(1, 'rgba(40,120,255,0)');
    g.fillStyle = grd;
    g.beginPath();
    g.ellipse(p.x, p.y, p.r, p.r * 0.62, 0, 0, U.TAU);
    g.fill();
    g.strokeStyle = 'rgba(180,240,255,' + (0.34 * a) + ')';
    g.lineWidth = 2;
    g.beginPath();
    g.ellipse(p.x, p.y, p.r * (0.9 + Math.sin(p.life * 6) * 0.05), p.r * 0.56, 0, 0, U.TAU);
    g.stroke();
  }

  function drawAura(g, p) {
    var pulse = 0.9 + Math.sin(p.life * 3) * 0.06;
    var grd = g.createRadialGradient(p.x, p.y, p.r * 0.25, p.x, p.y, p.r * pulse);
    grd.addColorStop(0, 'rgba(150,255,190,0.05)');
    grd.addColorStop(0.75, 'rgba(110,240,170,0.13)');
    grd.addColorStop(1, 'rgba(80,220,150,0.26)');
    g.fillStyle = grd;
    g.beginPath();
    g.ellipse(p.x, p.y, p.r * pulse, p.r * pulse * 0.78, 0, 0, U.TAU);
    g.fill();
    g.strokeStyle = 'rgba(170,255,210,0.34)';
    g.lineWidth = 1.6;
    g.stroke();
  }

  function drawSweep(g, p) {
    var t = p.life / p.maxLife;
    var a = Math.min(1, t * 1.6);
    g.save();
    g.translate(p.x, p.y);
    g.rotate(p.angle);
    // A crescent that sweeps outward as it fades.
    var reach = p.r * (1.25 - t * 0.25);
    var half = p.arc / 2;
    g.beginPath();
    g.arc(0, 0, reach, -half, half);
    g.arc(0, 0, reach * 0.42, half, -half, true);
    g.closePath();
    var grd = g.createRadialGradient(0, 0, reach * 0.35, 0, 0, reach);
    grd.addColorStop(0, 'rgba(255,240,210,' + (0.05 * a) + ')');
    grd.addColorStop(0.6, 'rgba(255,205,140,' + (0.4 * a) + ')');
    grd.addColorStop(1, 'rgba(255,150,80,' + (0.06 * a) + ')');
    g.fillStyle = grd;
    g.fill();
    g.strokeStyle = 'rgba(255,235,190,' + (0.6 * a) + ')';
    g.lineWidth = 2.5;
    g.beginPath();
    g.arc(0, 0, reach, -half, half);
    g.stroke();
    g.restore();
  }

  function drawStrike(g, p) {
    var t = p.life / p.maxLife;
    var a = Math.min(1, t * 2);
    g.save();
    g.strokeStyle = 'rgba(226,214,255,' + a + ')';
    g.lineWidth = 3.5;
    g.beginPath();
    var x = p.x + (p.seedX || 0);
    g.moveTo(x, p.y - 420);
    var steps = 7;
    for (var i = 1; i <= steps; i++) {
      var f = i / steps;
      var jitter = (1 - f) * 26;
      g.lineTo(U.lerp(x, p.x, f) + Math.sin(i * 12.9898 + (p.seedX || 0)) * jitter, p.y - 420 * (1 - f));
    }
    g.stroke();
    g.strokeStyle = 'rgba(255,255,255,' + (a * 0.8) + ')';
    g.lineWidth = 1.4;
    g.stroke();
    g.strokeStyle = 'rgba(200,180,255,' + (a * 0.7) + ')';
    g.lineWidth = 2;
    g.beginPath();
    g.ellipse(p.x, p.y, p.r * (1.1 - t * 0.3), p.r * 0.5 * (1.1 - t * 0.3), 0, 0, U.TAU);
    g.stroke();
    g.restore();
  }

  function emitLights() {
    var budget = 40;
    pool.each(function (p) {
      if (budget <= 0) return;
      if (!VS.render.visible(p.x, p.y, p.r + 60)) return;
      budget--;
      switch (p.kind) {
        case 'shot':
          VS.render.light(p.x, p.y, 46 * p.scale, 0.5);
          VS.render.glow(p.x, p.y, 34 * p.scale, p.color, 0.4);
          break;
        case 'arc':
          VS.render.light(p.x, p.y, 40, 0.45);
          VS.render.glow(p.x, p.y, 30, '200,220,255', 0.3);
          break;
        case 'lob':
          VS.render.light(p.x, p.y, 44, 0.5);
          VS.render.glow(p.x, p.y, 32, '120,220,255', 0.35);
          break;
        case 'pool':
          VS.render.light(p.x, p.y, p.r * 1.4, 0.45);
          VS.render.glow(p.x, p.y, p.r * 1.1, '90,190,255', 0.12);
          break;
        case 'aura':
          VS.render.light(p.x, p.y, p.r * 1.2, 0.35);
          VS.render.glow(p.x, p.y, p.r, '90,230,150', 0.14);
          break;
        case 'orbit':
          VS.render.light(p.x, p.y, 44, 0.55);
          VS.render.glow(p.x, p.y, 34, '255,190,90', 0.4);
          break;
        case 'sweep':
          VS.render.light(p.x, p.y, p.r * 1.2, 0.5 * (p.life / p.maxLife));
          VS.render.glow(p.x, p.y, p.r, '255,190,120', 0.3 * (p.life / p.maxLife));
          break;
        case 'strike':
          VS.render.light(p.x, p.y, 150, p.life / p.maxLife);
          VS.render.glow(p.x, p.y, 120, '200,180,255', 0.5 * (p.life / p.maxLife));
          break;
      }
    });
  }

  function clear() { pool.clear(); }

  return {
    pool: pool, spawn: spawn, update: update, resolve: resolve,
    drawGround: drawGround, drawAir: drawAir, emitLights: emitLights, clear: clear,
    count: function () { return pool.count(); }
  };
})();

/* Bootstrap: size the canvas to the window, then run a fixed-step simulation
   with an uncapped render.

   The simulation is locked to 60 Hz so a thousand enemies behave identically on
   a 144 Hz monitor and on a struggling laptop; when frames run long the loop
   drops simulation steps rather than letting dt explode and teleporting the
   horde through the player. */
(function () {
  var canvas = document.getElementById('screen');

  var STEP = 1 / 60;
  var MAX_STEPS = 4;
  var acc = 0;
  var last = 0;
  var running = true;
  var frameSamples = [];

  function step(dt) {
    VS.game.update(dt);
    VS.input.endStep();
  }

  function frame(now) {
    if (!running) return;
    if (!last) last = now;
    var elapsed = (now - last) / 1000;
    last = now;
    if (elapsed > 0.25) elapsed = 0.25;
    acc += elapsed;

    var steps = 0;
    var t0 = now;
    while (acc >= STEP && steps < MAX_STEPS) {
      step(STEP);
      acc -= STEP;
      steps++;
    }
    if (steps === MAX_STEPS) acc = 0;      // give up on the backlog, stay live

    VS.game.draw(elapsed);

    // Rolling frame cost, shown by the debug overlay and read by the tests.
    if (window.performance && performance.now) {
      var cost = performance.now() - t0;
      frameSamples.push(cost);
      if (frameSamples.length > 120) frameSamples.shift();
      VS.game.data.frameMs = cost;
    }

    window.requestAnimationFrame(frame);
  }

  function onResize() {
    VS.render.resize();
    VS.game.onResize();
  }

  function boot() {
    VS.render.attach(canvas);
    VS.input.attach(canvas);
    VS.game.init();

    window.addEventListener('resize', onResize);
    window.addEventListener('orientationchange', function () {
      // iOS reports the old size during the rotation itself.
      setTimeout(onResize, 120);
    });
    if (window.visualViewport) window.visualViewport.addEventListener('resize', onResize);

    window.addEventListener('pointerdown', function once() {
      VS.audio.unlock();
      window.removeEventListener('pointerdown', once);
    });

    window.requestAnimationFrame(frame);

    /* Headless hook. Lets a test drive the simulation deterministically without
       waiting on requestAnimationFrame, and read the state it cares about. */
    VS.probe = {
      version: 1,
      get state() { return VS.game.data.state; },
      get elapsed() { return VS.game.data.elapsed; },
      get level() { return VS.player.state.level; },
      get hp() { return VS.player.state.stats.hp; },
      get kills() { return VS.player.state.kills; },
      get enemies() { return VS.enemies.count(); },
      get projectiles() { return VS.projectiles.count(); },
      get gems() { return VS.pickups.count(); },
      get particles() { return VS.particles.count(); },
      get weapons() {
        var out = [];
        for (var i = 0; i < VS.weapons.owned.length; i++) {
          out.push({ id: VS.weapons.owned[i].id, level: VS.weapons.owned[i].level });
        }
        return out;
      },
      get options() {
        var out = [];
        for (var i = 0; i < VS.game.data.options.length; i++) {
          var o = VS.game.data.options[i];
          out.push({ kind: o.kind, id: o.id, name: o.name, level: o.level, isNew: o.isNew });
        }
        return out;
      },
      get boss() {
        var b = VS.enemies.boss;
        return b ? { alive: b.alive, hp: b.hp, maxHp: b.maxHp } : null;
      },
      get view() {
        return { w: VS.render.width, h: VS.render.height, zoom: VS.render.zoom,
          worldW: VS.render.view.x1 - VS.render.view.x0, worldH: VS.render.view.y1 - VS.render.view.y0 };
      },
      get frameStats() {
        if (!frameSamples.length) return null;
        var s = frameSamples.slice().sort(function (a, b) { return a - b; });
        return {
          samples: s.length,
          median: +s[Math.floor(s.length / 2)].toFixed(2),
          p95: +s[Math.floor(s.length * 0.95)].toFixed(2),
          max: +s[s.length - 1].toFixed(2)
        };
      },
      start: function () { VS.game.start(); },
      tick: function (seconds, opts) {
        opts = opts || {};
        var n = Math.round(seconds / STEP);
        for (var i = 0; i < n; i++) {
          if (opts.hold) for (var k = 0; k < opts.hold.length; k++) VS.input.tap(opts.hold[k]);
          step(STEP);
          if (opts.hold) for (var j = 0; j < opts.hold.length; j++) VS.input.release(opts.hold[j]);
        }
        return n;
      },
      press: function (action) { VS.input.tap(action); },
      render: function () { VS.game.draw(STEP); },
      skipTo: function (seconds) { VS.game.data.elapsed = seconds; },
      grantLevels: function (n) { VS.game.queueLevelUp(n); },
      choose: function (i) { VS.game.chooseOption(i); },
      pauseLoop: function () { running = false; },
      resumeLoop: function () {
        if (running) return;
        running = true;
        last = 0;
        window.requestAnimationFrame(frame);
      }
    };
    window.VS = VS;
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

/* The director: who shows up, how many, how hard, and when the ground shakes.

   Two things run in parallel:
     - a continuous pressure system that tops the field up toward a population
       target which grows with the clock, drawing from a type mix that unlocks
       new monsters minute by minute;
     - a schedule of set pieces (swarms, walls, elite packs, bosses) that punch
       through the steady rhythm.
   Everything spawns on a ring just outside the visible field, so nothing ever
   appears on top of the player, however wide the window is. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.director = (function () {
  var U = VS.util;
  var E = VS.enemies;

  var RUN_LENGTH = 900;               // 15 minutes to the final boss
  var POP_CAP = 700;

  var state = {
    t: 0,
    spawnTimer: 0,
    schedule: null,
    index: 0,
    bossAlive: false,
    bossKills: 0,
    intensity: 0,
    finished: false
  };

  var rng = new U.Rng(0x1f2e3d4c ^ (Date.now() & 0xffff));

  /* Unlock table: [fromMinute, type, weight]. */
  var MIX = [
    [0, 'bat', 10], [0, 'zombie', 8],
    [1, 'skeleton', 9], [2, 'slime', 7],
    [3, 'ghost', 8], [4, 'zombie', 6],
    [5, 'wraith', 6], [6, 'skeleton', 8],
    [7, 'brute', 2], [8, 'wraith', 8],
    [10, 'brute', 4], [12, 'wraith', 12]
  ];

  function pickType(minutes) {
    var total = 0, i;
    for (i = 0; i < MIX.length; i++) if (MIX[i][0] <= minutes) total += MIX[i][2];
    var pick = rng.float() * total, acc = 0;
    for (i = 0; i < MIX.length; i++) {
      if (MIX[i][0] > minutes) continue;
      acc += MIX[i][2];
      if (pick <= acc) return MIX[i][1];
    }
    return 'bat';
  }

  /* A point on a ring outside the view, with the ring sized from the actual
     window so a wide monitor spawns further out rather than seeing pop-in. */
  function ringPoint(out, angle, pad) {
    var view = VS.render.view;
    var rx = (view.x1 - view.x0) * 0.5 + (pad || 90);
    var ry = (view.y1 - view.y0) * 0.5 + (pad || 90);
    var p = VS.player.state;
    out.x = p.x + Math.cos(angle) * rx;
    out.y = p.y + Math.sin(angle) * ry;
    return out;
  }

  var pt = { x: 0, y: 0 };

  function spawnAtRing(type, angle, opts) {
    ringPoint(pt, angle);
    return E.spawn(type, pt.x, pt.y, opts);
  }

  function spawnScatter(count, minutes) {
    for (var i = 0; i < count; i++) {
      if (E.count() >= POP_CAP) return;
      spawnAtRing(pickType(minutes), rng.float() * U.TAU);
    }
  }

  /* A closing circle: the single most recognisable shape in the genre. */
  function swarmCircle(type, count, opts) {
    var base = rng.float() * U.TAU;
    for (var i = 0; i < count; i++) {
      if (E.count() >= POP_CAP) return;
      spawnAtRing(type, base + (i / count) * U.TAU, opts);
    }
  }

  /* A wall marching in from one side. */
  function wall(type, count, opts) {
    var side = rng.float() * U.TAU;
    var spread = 0.8;
    for (var i = 0; i < count; i++) {
      if (E.count() >= POP_CAP) return;
      var a = side + (i / count - 0.5) * spread;
      ringPoint(pt, a, 90 + (i % 4) * 46);
      E.spawn(type, pt.x, pt.y, opts);
    }
  }

  function elitePack(type, count) {
    for (var i = 0; i < count; i++) {
      spawnAtRing(type, rng.float() * U.TAU, { elite: true });
    }
    VS.audio.bossWarn();
  }

  function summonBoss(hpMul) {
    var e = spawnAtRing('king', rng.float() * U.TAU, { hpMul: hpMul });
    if (e) {
      state.bossAlive = true;
      VS.audio.bossWarn();
      VS.render.shake(1.0);
    }
    // The boss never arrives alone.
    swarmCircle('skeleton', 26);
    return e;
  }

  function buildSchedule() {
    var s = [];
    function at(t, label, fn) { s.push({ t: t, label: label, fn: fn, fired: false }); }

    at(45, '', function () { swarmCircle('bat', 26); });
    at(75, '', function () { wall('zombie', 22); });
    at(110, '', function () { swarmCircle('bat', 34); });
    at(140, 'ELITE', function () { elitePack('zombie', 2); });
    at(170, '', function () { wall('skeleton', 26); });
    at(200, '', function () { swarmCircle('slime', 22); });
    at(230, 'ELITE', function () { elitePack('skeleton', 3); });
    at(260, '', function () { wall('ghost', 28); });
    at(290, '', function () { swarmCircle('bat', 48); });
    at(300, 'BOSS', function () { summonBoss(1); });
    at(345, '', function () { wall('skeleton', 30); });
    at(380, 'ELITE', function () { elitePack('wraith', 3); });
    at(410, '', function () { swarmCircle('ghost', 34); });
    at(440, '', function () { wall('slime', 26); });
    at(470, '', function () { swarmCircle('wraith', 16); });
    at(500, 'ELITE', function () { elitePack('brute', 2); });
    at(530, '', function () { wall('zombie', 40); });
    at(560, '', function () { swarmCircle('skeleton', 44); });
    at(600, 'BOSS', function () { summonBoss(1.8); });
    at(650, '', function () { wall('wraith', 22); });
    at(690, 'ELITE', function () { elitePack('brute', 3); });
    at(720, '', function () { swarmCircle('ghost', 46); });
    at(760, '', function () { wall('skeleton', 48); });
    at(800, 'ELITE', function () { elitePack('wraith', 5); });
    at(840, '', function () { swarmCircle('bat', 64); });
    at(870, '', function () { wall('brute', 8); });
    at(RUN_LENGTH, 'FINAL', function () { summonBoss(3); });

    s.sort(function (a, b) { return a.t - b.t; });
    return s;
  }

  function reset() {
    state.t = 0;
    state.spawnTimer = 0.5;
    state.schedule = buildSchedule();
    state.index = 0;
    state.bossAlive = false;
    state.bossKills = 0;
    state.intensity = 0;
    state.finished = false;
    E.setScaling(1, 1, 1);
  }

  /* Difficulty curve. Health climbs steeply (the main knob), speed barely moves
     so the game never becomes unoutrunnable, damage climbs slowly. */
  function scalingFor(t) {
    var m = t / 60;
    return {
      hp: 1 + Math.pow(m, 1.5) * 0.42,
      speed: Math.min(1.45, 1 + m * 0.022),
      dmg: 1 + m * 0.14
    };
  }

  function populationTarget(t) {
    var m = t / 60;
    return Math.min(POP_CAP, Math.floor(20 + m * 22 + m * m * 1.9));
  }

  function update(dt) {
    state.t += dt;
    var t = state.t;
    var minutes = t / 60;

    var sc = scalingFor(t);
    E.setScaling(sc.hp, sc.speed, sc.dmg);

    // Set pieces.
    var sch = state.schedule;
    for (var i = 0; i < sch.length; i++) {
      if (!sch[i].fired && t >= sch[i].t) {
        sch[i].fired = true;
        sch[i].fn();
      }
    }

    // Steady pressure toward the population target.
    var target = populationTarget(t);
    var have = E.count();
    state.spawnTimer -= dt;
    if (state.spawnTimer <= 0) {
      state.spawnTimer = U.clamp(0.85 - minutes * 0.05, 0.25, 0.9);
      if (have < target) {
        var batch = Math.min(14, Math.ceil((target - have) * 0.18) + 1);
        spawnScatter(batch, minutes);
      }
    }

    state.bossAlive = !!(E.boss && E.boss.alive);
    state.intensity = U.clamp(have / 260, 0, 1) * 0.6 + U.clamp(minutes / 15, 0, 1) * 0.4;
    VS.audio.setIntensity(state.intensity);
  }

  /* Label for the next scheduled event, so the HUD can warn the player. */
  function nextEvent() {
    var sch = state.schedule;
    if (!sch) return null;
    for (var i = 0; i < sch.length; i++) {
      if (!sch[i].fired && sch[i].label) return sch[i];
    }
    return null;
  }

  return {
    RUN_LENGTH: RUN_LENGTH,
    state: state,
    reset: reset,
    update: update,
    nextEvent: nextEvent,
    populationTarget: populationTarget,
    scalingFor: scalingFor,
    summonBoss: summonBoss,
    swarmCircle: swarmCircle
  };
})();

/* Passives and the level-up offer.

   Passives are pure data: a level count plus a function that folds into the
   player's stats. Stats are recomputed from base every time something changes,
   so there is no drift and no order dependency. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.upgrades = (function () {
  var U = VS.util;

  var PASSIVES = {
    might: {
      name: 'Might', icon: 'icon_might', max: 5,
      text: function () { return '+12% damage from every weapon.'; },
      apply: function (s, lv) { s.might *= 1 + 0.12 * lv; }
    },
    cooldown: {
      name: 'Haste', icon: 'icon_cooldown', max: 5,
      text: function () { return '-7% weapon cooldown.'; },
      apply: function (s, lv) { s.cooldown *= Math.pow(0.93, lv); }
    },
    area: {
      name: 'Reach', icon: 'icon_area', max: 5,
      text: function () { return '+10% weapon size and range.'; },
      apply: function (s, lv) { s.area *= 1 + 0.1 * lv; }
    },
    amount: {
      name: 'Multiplicity', icon: 'icon_amount', max: 2,
      text: function () { return '+1 projectile for every weapon that fires one.'; },
      apply: function (s, lv) { s.amount += lv; }
    },
    duration: {
      name: 'Lingering', icon: 'icon_cooldown', max: 3,
      text: function () { return '+20% effect duration.'; },
      apply: function (s, lv) { s.duration *= 1 + 0.2 * lv; }
    },
    speed: {
      name: 'Swiftness', icon: 'icon_speed', max: 5,
      text: function () { return '+8% movement speed.'; },
      apply: function (s, lv) { s.speed *= 1 + 0.08 * lv; }
    },
    armor: {
      name: 'Armour', icon: 'icon_armor', max: 5,
      text: function () { return 'Take 2 less damage from every hit.'; },
      apply: function (s, lv) { s.armor += 2 * lv; }
    },
    maxhp: {
      name: 'Vitality', icon: 'icon_heart', max: 5,
      text: function () { return '+30 maximum health, and heal that much now.'; },
      apply: function (s, lv) { s.maxHp += 30 * lv; }
    },
    regen: {
      name: 'Recovery', icon: 'icon_heart', max: 4,
      text: function () { return 'Regenerate 0.5 health per second.'; },
      apply: function (s, lv) { s.regen += 0.5 * lv; }
    },
    magnet: {
      name: 'Lodestone', icon: 'icon_magnet', max: 4,
      text: function () { return '+30% pickup radius.'; },
      apply: function (s, lv) { s.magnet *= 1 + 0.3 * lv; }
    },
    growth: {
      name: 'Avarice', icon: 'icon_growth', max: 4,
      text: function () { return '+12% experience from every gem.'; },
      apply: function (s, lv) { s.growth *= 1 + 0.12 * lv; }
    },
    revive: {
      name: 'Second Wind', icon: 'icon_revive', max: 1,
      text: function () { return 'Once, death instead restores 60% of your health.'; },
      apply: function () { /* handled as a counter, see applyAll */ }
    }
  };

  var PASSIVE_ORDER = ['might', 'cooldown', 'area', 'amount', 'duration', 'speed',
    'armor', 'maxhp', 'regen', 'magnet', 'growth', 'revive'];

  var levels = {};
  var rng = new U.Rng(Date.now() & 0x7fffffff);

  var BASE = {
    maxHp: 140, speed: 190, might: 1, area: 1, cooldown: 1, duration: 1,
    amount: 0, magnet: 155, armor: 0, regen: 0, growth: 1, luck: 0
  };

  function reset() {
    levels = {};
    for (var k in PASSIVES) levels[k] = 0;
  }

  /* Recompute derived stats from base + every passive level. */
  function applyAll(player) {
    var s = player.stats;
    var hpBefore = s.hp, maxBefore = s.maxHp;
    s.maxHp = BASE.maxHp;
    s.speed = BASE.speed;
    s.might = BASE.might;
    s.area = BASE.area;
    s.cooldown = BASE.cooldown;
    s.duration = BASE.duration;
    s.amount = BASE.amount;
    s.magnet = BASE.magnet;
    s.armor = BASE.armor;
    s.regen = BASE.regen;
    s.growth = BASE.growth;

    for (var id in PASSIVES) {
      var lv = levels[id] || 0;
      if (lv > 0) PASSIVES[id].apply(s, lv);
    }
    player.revives = levels.revive || 0;

    // Vitality heals for what it added rather than silently widening the bar.
    if (s.maxHp > maxBefore) s.hp = Math.min(s.maxHp, hpBefore + (s.maxHp - maxBefore));
    else s.hp = Math.min(s.hp, s.maxHp);
  }

  function describePassive(id) {
    var def = PASSIVES[id];
    var lv = (levels[id] || 0) + 1;
    return {
      kind: 'passive',
      id: id,
      name: def.name,
      icon: def.icon,
      level: lv,
      isNew: lv === 1,
      text: def.text(lv),
      max: def.max
    };
  }

  /* Weighted pick of `count` distinct options.

     Weights lean toward levelling what you already carry: an offer of three
     brand-new things every level makes builds mush. */
  function roll(count) {
    var pool = [];
    var i, id;

    for (i = 0; i < VS.weapons.owned.length; i++) {
      var w = VS.weapons.owned[i];
      if (w.level < VS.weapons.MAX_LEVEL) pool.push({ weight: 12, opt: VS.weapons.describe(w.id) });
    }
    if (!VS.weapons.slotsFull()) {
      for (i = 0; i < VS.weapons.ORDER.length; i++) {
        id = VS.weapons.ORDER[i];
        if (!VS.weapons.has(id)) pool.push({ weight: 9, opt: VS.weapons.describe(id) });
      }
    }
    for (i = 0; i < PASSIVE_ORDER.length; i++) {
      id = PASSIVE_ORDER[i];
