    while (out.length < count && pool.length > 0) {
      var total = 0;
      for (i = 0; i < pool.length; i++) total += pool[i].weight;
      var pick = rng.float() * total, acc = 0, chosen = 0;
      for (i = 0; i < pool.length; i++) {
