      }
      out.push(pool[chosen].opt);
      pool.splice(chosen, 1);
    }

    // Nothing left to learn: offer something that is still worth taking.
    while (out.length < count) {
      out.push({
        kind: 'filler', id: 'heal', name: 'Blood Vial', icon: 'icon_heart',
        level: 1, isNew: false, text: 'Restore 40 health.'
      });
