    }
  }

  function ownedPassives(out) {
    out.length = 0;
    for (var i = 0; i < PASSIVE_ORDER.length; i++) {
      var id = PASSIVE_ORDER[i];
      if (levels[id] > 0) out.push({ id: id, level: levels[id], icon: PASSIVES[id].icon, name: PASSIVES[id].name });
    }
    return out;
  }

