    var s = player.stats;
    if (s.hp >= s.maxHp) return;
    var w = 40, x = player.x - w / 2, y = player.y + 8;
    g.fillStyle = 'rgba(0,0,0,0.6)';
    g.fillRect(x - 1, y - 1, w + 2, 6);
    var frac = U.clamp(s.hp / s.maxHp, 0, 1);
    g.fillStyle = frac > 0.5 ? '#6bd97a' : (frac > 0.25 ? '#ffc45a' : '#ff5a6a');
    g.fillRect(x, y, w * frac, 4);
  }

  function healthPanel(g, W, H, player) {
    var s = player.stats;
    var w = 190, h = 20, x = 12, y = H - 30;
    R.roundRect(g, x, y, w, h, 9);
    g.fillStyle = 'rgba(8,8,18,0.8)';
    g.fill();
    var frac = U.clamp(s.hp / s.maxHp, 0, 1);
    R.roundRect(g, x + 2, y + 2, (w - 4) * frac, h - 4, 7);
    var grd = g.createLinearGradient(x, y, x, y + h);
    grd.addColorStop(0, frac > 0.35 ? '#8bef98' : '#ff8a96');
    grd.addColorStop(1, frac > 0.35 ? '#399c55' : '#c02f45');
    g.fillStyle = grd;
    g.fill();
    R.text(g, Math.ceil(s.hp) + ' / ' + Math.round(s.maxHp), x + w / 2, y + 15, 13, '#ffffff', {
      align: 'center', shadow: false, stroke: 'rgba(0,0,0,0.7)', strokeWidth: 3
    });
  }

  /* Owned weapons and passives, with a pip row for level. */
  function loadout(g, W, H) {
    var iconSize = 34, gap = 6;
    var x = 12, y = H - 74;
    var i;
    for (i = 0; i < VS.weapons.owned.length; i++) {
      var w = VS.weapons.owned[i];
      var def = VS.weapons.DEFS[w.id];
      drawSlot(g, x + i * (iconSize + gap), y, iconSize, def.icon, w.level, VS.weapons.MAX_LEVEL, '#ffd9a8');
    }
    var list = VS.upgrades.ownedPassives(passiveBuf);
    var y2 = y - iconSize - gap;
    for (i = 0; i < list.length && i < 8; i++) {
      drawSlot(g, x + i * (iconSize + gap), y2, iconSize, list[i].icon, list[i].level,
        VS.upgrades.PASSIVES[list[i].id].max, '#bfd0ff');
    }
  }

  function drawSlot(g, x, y, size, icon, level, maxLevel, tint) {
    R.roundRect(g, x, y, size, size, 8);
    g.fillStyle = 'rgba(10,10,22,0.72)';
    g.fill();
    g.strokeStyle = level >= maxLevel ? 'rgba(255,215,130,0.9)' : 'rgba(120,130,200,0.35)';
    g.lineWidth = 1.5;
    g.stroke();
    var sp = VS.art.get(icon);
    if (sp) g.drawImage(sp.canvas, x + 3, y + 3, size - 6, size - 6);
    // level pips along the bottom edge
    var pipW = (size - 8) / maxLevel;
    for (var i = 0; i < maxLevel; i++) {
      g.fillStyle = i < level ? tint : 'rgba(255,255,255,0.16)';
      g.fillRect(x + 4 + i * pipW, y + size - 4, Math.max(1, pipW - 1), 2);
    }
  }

  function bossBar(g, W) {
    var boss = VS.enemies.boss;
    if (!boss || !boss.alive) return;
    var w = Math.min(560, W - 80), x = (W - w) / 2, y = 62;
    R.text(g, 'THE BONE KING', W / 2, y - 6, 14, '#ffb0c0', { align: 'center' });
    g.fillStyle = 'rgba(8,8,18,0.85)';
    g.fillRect(x, y, w, 12);
    var frac = U.clamp(boss.hp / boss.maxHp, 0, 1);
    var grd = g.createLinearGradient(x, y, x + w, y);
    grd.addColorStop(0, '#ff4d6a');
    grd.addColorStop(1, '#ff9a5a');
    g.fillStyle = grd;
    g.fillRect(x, y, w * frac, 12);
    g.strokeStyle = 'rgba(255,190,200,0.5)';
    g.lineWidth = 1;
    g.strokeRect(x + 0.5, y + 0.5, w - 1, 11);
  }

  /* A short banner for set pieces, so a wall of skeletons is announced rather
     than just happening. */
  var banner = { text: '', life: 0, color: '#ffd9a8' };
  function announce(text, color) {
    banner.text = text;
    banner.life = 2.4;
    banner.color = color || '#ffd9a8';
  }
  function updateBanner(dt) { if (banner.life > 0) banner.life -= dt; }
  function drawBanner(g, W, H) {
    if (banner.life <= 0) return;
    var t = Math.min(1, banner.life / 0.5);
    var y = H * 0.26;
    g.save();
    g.globalAlpha = t;
    R.text(g, banner.text, W / 2, y, 34, banner.color, {
      align: 'center', shadow: false, stroke: 'rgba(0,0,0,0.85)', strokeWidth: 6
    });
    g.restore();
  }

  /* The touch stick: only drawn while a finger is down. */
  function touchStick(g) {
    var st = VS.input.stick;
    if (!st.active) return;
    var range = VS.input.stickRange;
    g.save();
    g.globalAlpha = 0.4;
    g.strokeStyle = '#cfd8ff';
    g.lineWidth = 2;
    g.beginPath(); g.arc(st.ox, st.oy, range, 0, U.TAU); g.stroke();
    g.fillStyle = 'rgba(200,215,255,0.5)';
    g.beginPath(); g.arc(st.ox + st.dx * range, st.oy + st.dy * range, 18, 0, U.TAU); g.fill();
    g.restore();
  }

  function draw(g, game) {
    var W = R.width, H = R.height;
    var player = VS.player.state;
    xpBar(g, W, player);
    timer(g, W, game.elapsed, VS.director.state.bossAlive);
    stats(g, W, game);
    bossBar(g, W);
    loadout(g, W, H);
    healthPanel(g, W, H, player);
    drawBanner(g, W, H);
    touchStick(g);
  }

  return {
    draw: draw,
    healthWorld: healthWorld,
    announce: announce,
    updateBanner: updateBanner,
    banner: banner
  };
})();

/* Full-screen states: title, the level-up choice, pause, death and victory.

   The choice screen is the heart of the genre, so it gets the most care: three
   cards, laid out across the window on a wide screen and stacked on a narrow
   one, pickable with the mouse, a finger, 1/2/3, or the arrow keys. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.screens = (function () {
  var U = VS.util;
  var R = VS.render;

  var cards = [];                     // rects for the current choice layout

  function dim(g, W, H, alpha) {
    g.fillStyle = 'rgba(4,4,12,' + (alpha === undefined ? 0.72 : alpha) + ')';
    g.fillRect(0, 0, W, H);
  }

  function wrap(g, text, maxWidth, size) {
    g.font = '400 ' + size + 'px ' + R.FONT;
    var words = String(text).split(' ');
    var lines = [];
    var line = '';
    for (var i = 0; i < words.length; i++) {
      var test = line ? line + ' ' + words[i] : words[i];
      if (g.measureText(test).width > maxWidth && line) {
        lines.push(line);
        line = words[i];
      } else {
        line = test;
      }
    }
    if (line) lines.push(line);
    return lines;
  }

  /* ---- level-up choice ---------------------------------------------------- */
  function layoutCards(options) {
    var W = R.width, H = R.height;
    cards.length = 0;
    var n = options.length;
    var stacked = W < 760;
    if (stacked) {
      var cw = Math.min(460, W - 40);
      var ch = Math.min(112, (H - 220) / n);
      var top = H / 2 - (ch * n + 14 * (n - 1)) / 2 + 28;
      for (var i = 0; i < n; i++) {
        cards.push({ x: (W - cw) / 2, y: top + i * (ch + 14), w: cw, h: ch, stacked: true });
      }
    } else {
      var cw2 = Math.min(300, (W - 100) / n);
      var ch2 = Math.min(330, H - 260);
      var gap = Math.min(24, (W - cw2 * n) / (n + 1));
      var left = (W - (cw2 * n + gap * (n - 1))) / 2;
      var top2 = H / 2 - ch2 / 2 + 24;
      for (var j = 0; j < n; j++) {
        cards.push({ x: left + j * (cw2 + gap), y: top2, w: cw2, h: ch2, stacked: false });
      }
    }
    return cards;
  }

  function drawCard(g, card, opt, selected, index) {
    var x = card.x, y = card.y, w = card.w, h = card.h;
    var lift = selected ? 6 : 0;
    y -= lift;

    if (selected) {
      g.save();
      g.shadowColor = 'rgba(150,170,255,0.55)';
      g.shadowBlur = 26;
    }
    R.panel(g, x, y, w, h, {
      top: selected ? 'rgba(52,46,96,0.98)' : 'rgba(28,24,50,0.95)',
      bottom: selected ? 'rgba(26,22,52,0.98)' : 'rgba(14,12,30,0.96)',
      border: selected ? 'rgba(190,200,255,0.9)' : 'rgba(120,110,190,0.45)',
      borderWidth: selected ? 2.5 : 1.5,
      radius: 16
    });
    if (selected) g.restore();

    var iconSp = VS.art.get(opt.icon);
    if (card.stacked) {
      if (iconSp) g.drawImage(iconSp.canvas, x + 14, y + h / 2 - 22, 44, 44);
      R.text(g, opt.name, x + 70, y + 30, 19, opt.isNew ? '#ffd9a8' : '#eef0ff');
      if (opt.kind !== 'filler') {
        R.text(g, opt.isNew ? 'NEW' : 'LEVEL ' + opt.level, x + w - 14, y + 30, 13,
          opt.isNew ? '#ffd06b' : '#9fb0e8', { align: 'right' });
      }
      var lines = wrap(g, opt.text, w - 84, 14);
      for (var i = 0; i < lines.length && i < 3; i++) {
        R.text(g, lines[i], x + 70, y + 52 + i * 18, 14, '#c3c9e8', { weight: '400' });
      }
      R.text(g, String(index + 1), x + w - 16, y + h - 12, 13, 'rgba(180,190,240,0.5)', { align: 'right' });
    } else {
      if (iconSp) g.drawImage(iconSp.canvas, x + w / 2 - 32, y + 26, 64, 64);
      R.text(g, opt.name, x + w / 2, y + 118, 21, opt.isNew ? '#ffd9a8' : '#eef0ff', { align: 'center' });
      if (opt.kind !== 'filler') {
        R.text(g, opt.isNew ? 'NEW' : 'LEVEL ' + opt.level, x + w / 2, y + 140, 13,
          opt.isNew ? '#ffd06b' : '#9fb0e8', { align: 'center' });
      }
      var lines2 = wrap(g, opt.text, w - 40, 15);
      for (var j = 0; j < lines2.length && j < 5; j++) {
        R.text(g, lines2[j], x + w / 2, y + 176 + j * 21, 15, '#c3c9e8', { align: 'center', weight: '400' });
      }
      R.text(g, 'press ' + (index + 1), x + w / 2, y + h - 18, 13, 'rgba(180,190,240,0.55)', { align: 'center', weight: '400' });
    }
  }

  function drawLevelUp(g, options, selected, level) {
    var W = R.width, H = R.height;
    dim(g, W, H, 0.78);
    R.text(g, 'LEVEL ' + level, W / 2, H / 2 - (cards.length && !cards[0].stacked ? 210 : 150), 44, '#ffe9a8', {
      align: 'center', shadow: false, stroke: 'rgba(0,0,0,0.8)', strokeWidth: 6
    });
    R.text(g, 'Choose your reward', W / 2, H / 2 - (cards.length && !cards[0].stacked ? 176 : 122), 17, '#b9c2e8', {
      align: 'center', weight: '400'
    });
    for (var i = 0; i < options.length; i++) {
      drawCard(g, cards[i], options[i], i === selected, i);
    }
  }

  function hitTest(x, y) {
    for (var i = 0; i < cards.length; i++) {
      var c = cards[i];
      if (x >= c.x && x <= c.x + c.w && y >= c.y - 8 && y <= c.y + c.h) return i;
    }
    return -1;
  }

  /* ---- title -------------------------------------------------------------- */
  function drawTitle(g, t, best) {
    var W = R.width, H = R.height;
    dim(g, W, H, 0.55);

    var titleY = Math.min(H * 0.3, 230);
    var pulse = 1 + Math.sin(t * 1.6) * 0.012;
    g.save();
    g.translate(W / 2, titleY);
    g.scale(pulse, pulse);
    R.text(g, 'NIGHT HARVEST', 0, 0, Math.min(74, W / 9), '#ffe9b0', {
      align: 'center', shadow: false, stroke: 'rgba(20,6,20,0.9)', strokeWidth: 8
    });
    g.restore();
    R.text(g, 'survive fifteen minutes in the dark', W / 2, titleY + 36, Math.min(19, W / 28), '#c9b8ff', {
      align: 'center', weight: '400'
    });

    var boxW = Math.min(520, W - 60);
    var boxH = 168;
    var bx = (W - boxW) / 2, by = titleY + 70;
    R.panel(g, bx, by, boxW, boxH, { radius: 16 });

    var lines = [
      ['MOVE', 'WASD / arrows — or drag anywhere'],
      ['ATTACK', 'automatic, always'],
      ['LEVEL UP', 'pick one of three rewards'],
      ['PAUSE', 'Esc      SOUND  M']
    ];
    for (var i = 0; i < lines.length; i++) {
      R.text(g, lines[i][0], bx + 24, by + 38 + i * 32, 14, '#8fa0d8');
      R.text(g, lines[i][1], bx + 130, by + 38 + i * 32, 15, '#e6e9ff', { weight: '400' });
    }

    if (best > 0) {
      R.text(g, 'best survival  ' + U.formatTime(best), W / 2, by + boxH + 34, 16, '#ffd9a8', { align: 'center' });
    }
    if (Math.floor(t * 1.6) % 2 === 0) {
      R.text(g, 'press ENTER or click to begin', W / 2, by + boxH + (best > 0 ? 68 : 40), 19, '#ffffff', { align: 'center' });
    }
  }

  /* ---- pause / death / victory -------------------------------------------- */
  function drawPause(g) {
    var W = R.width, H = R.height;
    dim(g, W, H, 0.62);
    R.text(g, 'PAUSED', W / 2, H / 2 - 10, 46, '#ffffff', { align: 'center' });
    R.text(g, 'Esc to resume   ·   M for sound   ·   R to give up', W / 2, H / 2 + 26, 16, '#b9c2e8', {
      align: 'center', weight: '400'
    });
  }

  function statLine(g, label, value, x, y, w) {
    R.text(g, label, x, y, 15, '#94a0cc', { weight: '400' });
    R.text(g, value, x + w, y, 16, '#ffffff', { align: 'right' });
  }

  function drawResult(g, game, won, t) {
    var W = R.width, H = R.height;
    dim(g, W, H, 0.8);
    var player = VS.player.state;

    var boxW = Math.min(460, W - 48);
    var boxH = 300;
    var bx = (W - boxW) / 2, by = H / 2 - boxH / 2 + 20;

    R.text(g, won ? 'THE NIGHT IS OVER' : 'YOU FELL', W / 2, by - 34, Math.min(46, W / 11), won ? '#ffe9a8' : '#ff8fa3', {
      align: 'center', shadow: false, stroke: 'rgba(0,0,0,0.85)', strokeWidth: 6
    });

    R.panel(g, bx, by, boxW, boxH, { radius: 16 });
    var x = bx + 26, w = boxW - 52;
    statLine(g, 'survived', U.formatTime(game.elapsed), x, by + 44, w);
    statLine(g, 'level reached', String(player.level), x, by + 76, w);
    statLine(g, 'enemies slain', U.shortNumber(player.kills), x, by + 108, w);
    statLine(g, 'damage dealt', U.shortNumber(game.damageDealt), x, by + 140, w);
    statLine(g, 'best survival', U.formatTime(game.best), x, by + 172, w);

    // The build you died with.
    var ix = x, iy = by + 200;
    for (var i = 0; i < VS.weapons.owned.length; i++) {
      var def = VS.weapons.DEFS[VS.weapons.owned[i].id];
      var sp = VS.art.get(def.icon);
      if (sp) g.drawImage(sp.canvas, ix + i * 38, iy, 34, 34);
      R.text(g, String(VS.weapons.owned[i].level), ix + i * 38 + 30, iy + 34, 12, '#ffd9a8', { align: 'right' });
    }

    if (t > 1 && Math.floor(t * 1.6) % 2 === 0) {
      R.text(g, 'press ENTER to try again', W / 2, by + boxH + 34, 18, '#ffffff', { align: 'center' });
    }
  }

  return {
    layoutCards: layoutCards,
    drawLevelUp: drawLevelUp,
    hitTest: hitTest,
    drawTitle: drawTitle,
    drawPause: drawPause,
    drawResult: drawResult,
    cards: cards
  };
})();

/* Pooled effects: sparks, blood, smoke, embers, shards, expanding rings and
   floating numbers — plus a small pool of light flashes.

   Individual particles deliberately do NOT emit light: a radial gradient per
   particle would cost more than the rest of the frame put together. Events that
   should light the world spawn one flash instead, and the flash pool is capped. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.particles = (function () {
  var U = VS.util;

  var parts = new U.Pool(900, function () {
    return {
      alive: false, kind: 'spark', x: 0, y: 0, vx: 0, vy: 0, gy: 0,
      life: 0, maxLife: 1, size: 2, rot: 0, spin: 0, drag: 0.9,
      r: 255, g: 255, b: 255
    };
  });

  var texts = new U.Pool(48, function () {
    return { alive: false, x: 0, y: 0, vy: 0, life: 0, maxLife: 1, str: '', size: 14, color: '#fff' };
  });

  var rings = new U.Pool(28, function () {
    return { alive: false, x: 0, y: 0, r: 0, grow: 200, life: 0, maxLife: 0.4, color: '255,255,255', width: 3 };
  });

  var flashes = new U.Pool(20, function () {
    return { alive: false, x: 0, y: 0, r: 40, life: 0, maxLife: 0.3, color: '255,200,120', strength: 1 };
  });

  function spark(x, y, vx, vy, life, size, r, g, b) {
    var p = parts.spawn();
    if (!p) return;
    p.kind = 'spark';
    p.x = x; p.y = y; p.vx = vx; p.vy = vy; p.gy = 0;
    p.life = p.maxLife = life; p.size = size;
    p.r = r; p.g = g; p.b = b;
    p.drag = 0.86;
  }

  function blood(x, y, dirX, dirY, amount) {
    for (var i = 0; i < amount; i++) {
      var p = parts.spawn();
      if (!p) return;
      var a = Math.atan2(dirY, dirX) + (Math.random() - 0.5) * 1.6;
      var sp = 40 + Math.random() * 150;
      p.kind = 'blood';
      p.x = x; p.y = y;
      p.vx = Math.cos(a) * sp;
      p.vy = Math.sin(a) * sp - 40;
      p.gy = 320;
      p.life = p.maxLife = 0.35 + Math.random() * 0.4;
      p.size = 1.4 + Math.random() * 2.2;
      p.drag = 0.94;
      p.r = 150 + Math.random() * 60 | 0; p.g = 18; p.b = 34;
    }
  }

  function smoke(x, y, size, rise) {
    var p = parts.spawn();
    if (!p) return;
    p.kind = 'smoke';
    p.x = x; p.y = y;
    p.vx = (Math.random() - 0.5) * 30;
    p.vy = -(rise || 20) - Math.random() * 20;
    p.gy = 0;
    p.life = p.maxLife = 0.5 + Math.random() * 0.5;
    p.size = size;
    p.drag = 0.95;
    p.r = 90; p.g = 90; p.b = 110;
  }

  function ember(x, y, r, g, b) {
    var p = parts.spawn();
    if (!p) return;
    p.kind = 'ember';
    p.x = x; p.y = y;
    p.vx = (Math.random() - 0.5) * 14;
    p.vy = -22 - Math.random() * 26;
    p.gy = -6;
    p.life = p.maxLife = 0.6 + Math.random() * 0.7;
    p.size = 1 + Math.random() * 1.6;
    p.drag = 0.98;
    p.r = r === undefined ? 255 : r;
    p.g = g === undefined ? 170 : g;
    p.b = b === undefined ? 70 : b;
  }

  function shard(x, y, r, g, b) {
    var p = parts.spawn();
    if (!p) return;
    var a = Math.random() * U.TAU;
    var sp = 50 + Math.random() * 160;
    p.kind = 'shard';
    p.x = x; p.y = y;
    p.vx = Math.cos(a) * sp;
    p.vy = Math.sin(a) * sp - 60;
    p.gy = 420;
    p.life = p.maxLife = 0.5 + Math.random() * 0.5;
    p.size = 2 + Math.random() * 2.5;
    p.rot = Math.random() * U.TAU;
    p.spin = (Math.random() - 0.5) * 16;
    p.drag = 0.99;
    p.r = r; p.g = g; p.b = b;
  }

  function ring(x, y, color, grow, life, width, startR) {
    var r = rings.spawn();
    if (!r) return;
    r.x = x; r.y = y;
    r.r = startR || 2;
    r.grow = grow || 260;
    r.life = r.maxLife = life || 0.35;
    r.color = color || '255,255,255';
    r.width = width || 3;
  }

  function flash(x, y, radius, color, life, strength) {
    var f = flashes.spawn();
    if (!f) return;
    f.x = x; f.y = y; f.r = radius;
    f.color = color || '255,200,120';
    f.life = f.maxLife = life || 0.25;
    f.strength = strength === undefined ? 1 : strength;
  }

  function number(x, y, str, color, size) {
    var t = texts.spawn();
    if (!t) return;
    t.x = x; t.y = y;
    t.vy = -46;
    t.str = str;
    t.color = color || '#ffe9a8';
    t.size = size || 15;
    t.life = t.maxLife = 0.75;
  }

  /* Standard "something died" burst, scaled by body size. */
  function death(x, y, scale, r, g, b) {
    var n = Math.min(14, 4 + Math.floor(scale * 5));
    for (var i = 0; i < n; i++) {
      var a = Math.random() * U.TAU;
      var sp = (40 + Math.random() * 130) * scale;
      spark(x, y, Math.cos(a) * sp, Math.sin(a) * sp - 30, 0.25 + Math.random() * 0.3,
        1.4 + Math.random() * 2 * scale, r, g, b);
    }
    smoke(x, y, 7 * scale, 26);
    ring(x, y, r + ',' + g + ',' + b, 190 * scale, 0.22, 2.5 * scale);
  }

  function update(dt) {
    parts.each(function (p) {
      p.life -= dt;
      if (p.life <= 0) { parts.kill(p); return; }
      p.vy += p.gy * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      var d = Math.pow(p.drag, dt * 60);
      p.vx *= d; p.vy *= d;
      if (p.spin) p.rot += p.spin * dt;
    });
    rings.each(function (r) {
      r.life -= dt;
      if (r.life <= 0) { rings.kill(r); return; }
      r.r += r.grow * dt;
    });
    texts.each(function (t) {
      t.life -= dt;
      if (t.life <= 0) { texts.kill(t); return; }
      t.y += t.vy * dt;
      t.vy += 60 * dt;
    });
    flashes.each(function (f) {
      f.life -= dt;
      if (f.life <= 0) flashes.kill(f);
    });
  }

  function draw(g) {
    g.save();
    parts.each(function (p) {
      var t = p.life / p.maxLife;
      var c = p.r + ',' + p.g + ',' + p.b;
      if (p.kind === 'smoke') {
        g.fillStyle = 'rgba(' + c + ',' + (0.3 * t) + ')';
        g.beginPath();
        g.arc(p.x, p.y, p.size * (1.7 - t * 0.7), 0, U.TAU);
        g.fill();
      } else if (p.kind === 'shard') {
        g.save();
        g.translate(p.x, p.y);
        g.rotate(p.rot);
        g.fillStyle = 'rgba(' + c + ',' + Math.min(1, t * 1.6) + ')';
        g.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 1.4);
        g.restore();
      } else if (p.kind === 'blood') {
        g.fillStyle = 'rgba(' + c + ',' + Math.min(0.9, t * 1.4) + ')';
        g.beginPath();
        g.ellipse(p.x, p.y, p.size, p.size * 0.8, 0, 0, U.TAU);
        g.fill();
      } else {
        // spark / ember: a hot core that fades to its own colour
        var a = Math.min(1, t * 1.8);
        g.fillStyle = 'rgba(' + c + ',' + a + ')';
        g.beginPath();
        g.arc(p.x, p.y, p.size * (0.5 + t * 0.7), 0, U.TAU);
        g.fill();
        if (t > 0.55) {
          g.fillStyle = 'rgba(255,255,255,' + ((t - 0.55) * 1.4) + ')';
          g.beginPath();
          g.arc(p.x, p.y, p.size * 0.45, 0, U.TAU);
          g.fill();
        }
      }
    });

    rings.each(function (r) {
      var t = r.life / r.maxLife;
      g.strokeStyle = 'rgba(' + r.color + ',' + t + ')';
      g.lineWidth = Math.max(0.6, r.width * t);
      g.beginPath();
      g.arc(r.x, r.y, r.r, 0, U.TAU);
      g.stroke();
    });
    g.restore();
  }

  function drawText(g) {
    g.save();
    texts.each(function (t) {
      var a = Math.min(1, t.life / t.maxLife * 1.8);
      VS.render.text(g, t.str, t.x, t.y, t.size, t.color, {
        align: 'center', shadow: false, stroke: 'rgba(0,0,0,' + (0.7 * a) + ')', strokeWidth: 3
      });
      g.globalAlpha = 1;
    });
    g.restore();
  }

  /* Contribute the flash pool to the lighting pass. */
  function emitLights() {
    flashes.each(function (f) {
      var t = f.life / f.maxLife;
      VS.render.light(f.x, f.y, f.r * (1.4 - t * 0.4), Math.min(1, t * f.strength));
      VS.render.glow(f.x, f.y, f.r * (1.1 - t * 0.3), f.color, 0.5 * t * f.strength);
    });
  }

  function clear() { parts.clear(); rings.clear(); texts.clear(); flashes.clear(); }

  return {
    spark: spark, blood: blood, smoke: smoke, ember: ember, shard: shard,
    ring: ring, flash: flash, number: number, death: death,
    update: update, draw: draw, drawText: drawText, emitLights: emitLights,
    clear: clear,
    count: function () { return parts.count(); }
  };
})();

/* The endless graveyard.

   The ground is two seamless tiles at different sizes, drawn one over the other
   so the repeat never lines up into an obvious grid. Scenery is not stored at
   all: every 150-unit cell hashes its own world coordinates into "is there a
   prop here, which one, and where in the cell", so the map is infinite, costs
   no memory, and looks the same every time you walk back over it. */
var VS = (typeof VS !== 'undefined' && VS) || {};

VS.terrain = (function () {
  var U = VS.util;

  var TILE = 256;
  var MACRO = 384;
  var CELL = 150;

  var groundTile = null;
  var macroTile = null;

  /* A soft-edged patch of colour, repeated at every wrap offset so nothing
     breaks at the tile seam.

     These are radial gradients rather than polygons on purpose: an earlier pass
     drew jittered polygons and the ground came out looking like a quilt of
     tilted tiles. A gradient has no silhouette to notice. */
  function softBlob(g, size, x, y, r, color, alpha) {
    for (var ox = -1; ox <= 1; ox++) {
      for (var oy = -1; oy <= 1; oy++) {
        var px = x + ox * size, py = y + oy * size;
        if (px < -r || px > size + r || py < -r || py > size + r) continue;
        var grd = g.createRadialGradient(px, py, 0, px, py, r);
        grd.addColorStop(0, 'rgba(' + color + ',' + alpha + ')');
        grd.addColorStop(0.55, 'rgba(' + color + ',' + (alpha * 0.55) + ')');
        grd.addColorStop(1, 'rgba(' + color + ',0)');
        g.fillStyle = grd;
        g.beginPath();
        g.ellipse(px, py, r, r * 0.82, 0, 0, U.TAU);
        g.fill();
      }
    }
  }

  function buildGround() {
    var c = VS.art.canvas(TILE, TILE);
    var g = c.getContext('2d');
    var rng = new U.Rng(0x51a3f00d);

    // Deliberately brighter than it looks in game: the night layer takes about
    // half of this back out.
    g.fillStyle = '#33452f';
    g.fillRect(0, 0, TILE, TILE);

    var i;
    // Grass tone variation.
    for (i = 0; i < 40; i++) {
      softBlob(g, TILE, rng.range(0, TILE), rng.range(0, TILE), rng.range(30, 78),
        rng.chance(0.5) ? '74,102,58' : '38,56,40', rng.range(0.18, 0.4));
    }
    // Bare earth showing through.
    for (i = 0; i < 18; i++) {
      softBlob(g, TILE, rng.range(0, TILE), rng.range(0, TILE), rng.range(16, 44), '92,80,56', rng.range(0.2, 0.45));
    }
    // Pale sandy scuffs.
    for (i = 0; i < 10; i++) {
      softBlob(g, TILE, rng.range(0, TILE), rng.range(0, TILE), rng.range(10, 26), '126,116,88', rng.range(0.14, 0.3));
    }

    // Close-up texture: grass tufts and pebbles.
    for (i = 0; i < 340; i++) {
      var x = rng.range(0, TILE), y = rng.range(0, TILE);
      if (rng.chance(0.78)) {
        g.strokeStyle = rng.chance(0.5) ? 'rgba(126,164,108,0.5)' : 'rgba(88,124,80,0.45)';
        g.lineWidth = 1;
        g.beginPath();
        g.moveTo(x, y);
        g.quadraticCurveTo(x + rng.range(-1.5, 1.5), y - 2.5, x + rng.range(-2.5, 2.5), y - rng.range(3, 6));
        g.stroke();
      } else {
        g.fillStyle = 'rgba(150,150,138,0.35)';
        g.beginPath();
        g.ellipse(x, y, rng.range(0.8, 2.2), rng.range(0.6, 1.5), rng.range(0, 3), 0, U.TAU);
        g.fill();
      }
    }
    groundTile = c;
  }

  /* A second, larger, very soft layer. Its only job is to break the 256-unit
     repeat of the ground tile into something the eye cannot lock onto. */
  function buildMacro() {
    var c = VS.art.canvas(MACRO, MACRO);
    var g = c.getContext('2d');
    var rng = new U.Rng(0x2f19bb01);
    g.clearRect(0, 0, MACRO, MACRO);
    for (var i = 0; i < 22; i++) {
      softBlob(g, MACRO, rng.range(0, MACRO), rng.range(0, MACRO), rng.range(60, 150),
        rng.chance(0.55) ? '10,18,28' : '96,96,58', rng.range(0.08, 0.2));
    }
    macroTile = c;
  }

  function build() {
    buildGround();
    buildMacro();
  }

  function drawGround(g, view) {
    if (!groundTile) build();
    var x0 = Math.floor(view.x0 / TILE) * TILE;
    var y0 = Math.floor(view.y0 / TILE) * TILE;
    var x, y;
    for (y = y0; y < view.y1 + TILE; y += TILE) {
      for (x = x0; x < view.x1 + TILE; x += TILE) {
        g.drawImage(groundTile, x, y, TILE, TILE);
      }
    }
    g.globalAlpha = 0.85;
    var mx0 = Math.floor(view.x0 / MACRO) * MACRO;
    var my0 = Math.floor(view.y0 / MACRO) * MACRO;
    for (y = my0; y < view.y1 + MACRO; y += MACRO) {
      for (x = mx0; x < view.x1 + MACRO; x += MACRO) {
        g.drawImage(macroTile, x, y, MACRO, MACRO);
      }
    }
    g.globalAlpha = 1;
  }

  /* Prop table. `foot` is how far below the sprite's anchor the base sits, used
     for depth sorting against the cast. */
  var PROPS = [
    { sprite: 'grave0', weight: 16, light: 0 },
    { sprite: 'grave1', weight: 10, light: 0 },
    { sprite: 'grave2', weight: 10, light: 0 },
    { sprite: 'bush', weight: 14, light: 0 },
    { sprite: 'rock', weight: 12, light: 0 },
    { sprite: 'tree', weight: 12, light: 0 },
    { sprite: 'ruin', weight: 6, light: 0 },
    { sprite: 'torch', weight: 6, light: 1 }
  ];
  var TOTAL_WEIGHT = (function () {
    var t = 0;
    for (var i = 0; i < PROPS.length; i++) t += PROPS[i].weight;
    return t;
  })();

  var scratch = { x: 0, y: 0, sprite: '', light: 0, seed: 0 };

  /* Visit every prop whose cell overlaps the view. Reuses one object — callers
     must copy anything they keep. */
  function eachProp(view, fn) {
    var cx0 = Math.floor((view.x0 - CELL) / CELL);
    var cx1 = Math.floor((view.x1 + CELL) / CELL);
    var cy0 = Math.floor((view.y0 - CELL) / CELL);
    var cy1 = Math.floor((view.y1 + CELL) / CELL);
    for (var cy = cy0; cy <= cy1; cy++) {
      for (var cx = cx0; cx <= cx1; cx++) {
        var h = U.hash2(cx, cy);
        if (h > 0.42) continue;                       // most cells stay empty
        var h2 = U.hash2(cx + 9871, cy - 4231);
        var h3 = U.hash2(cx - 313, cy + 7717);
        var pick = h2 * TOTAL_WEIGHT;
        var acc = 0, def = PROPS[0];
        for (var i = 0; i < PROPS.length; i++) {
          acc += PROPS[i].weight;
          if (pick <= acc) { def = PROPS[i]; break; }
        }
        scratch.x = cx * CELL + 20 + (h / 0.42) * (CELL - 40);
        scratch.y = cy * CELL + 20 + h3 * (CELL - 40);
        scratch.sprite = def.sprite;
        scratch.light = def.light;
        scratch.seed = (cx * 31 + cy * 17) & 1023;
        fn(scratch);
      }
    }
  }

  return {
    build: build,
    drawGround: drawGround,
    eachProp: eachProp,
    CELL: CELL
  };
})();

/* Dev-only headless harness — NOT loaded by the game.
 *
 *   node tools/smoke-test.mjs
 *
 * Loads the same script files index.html loads into a stubbed DOM, drives the
 * simulation at a fixed 60 Hz and asserts the things this design is judged on:
 * weapons that fire themselves, an XP economy that opens a three-way choice,
 * difficulty that actually scales with the clock, a boss at the milestone, and
 * a simulation step that stays cheap with hundreds of enemies on the field.
 * Node 18+, no dependencies.
 */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';
import { performance } from 'node:perf_hooks';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/* ---- DOM / canvas stubs -------------------------------------------------- */
const noop = () => {};
function makeCtx() {
  const ctx = {
    canvas: null,
    globalAlpha: 1, globalCompositeOperation: 'source-over',
    fillStyle: '#000', strokeStyle: '#000', lineWidth: 1, lineJoin: 'round', lineCap: 'round',
    font: '', textAlign: 'left', textBaseline: 'alphabetic',
    imageSmoothingEnabled: true, shadowColor: '', shadowBlur: 0,
    createRadialGradient: () => ({ addColorStop: noop }),
    createLinearGradient: () => ({ addColorStop: noop }),
    measureText: (s) => ({ width: String(s).length * 7 })
  };
  for (const m of ['save', 'restore', 'translate', 'rotate', 'scale', 'setTransform', 'transform',
    'beginPath', 'closePath', 'moveTo', 'lineTo', 'arc', 'arcTo', 'ellipse', 'rect', 'roundRect',
    'quadraticCurveTo', 'bezierCurveTo', 'fill', 'stroke', 'clip', 'setLineDash',
    'fillRect', 'strokeRect', 'clearRect', 'drawImage', 'fillText', 'strokeText']) ctx[m] = noop;
  return ctx;
}
function makeCanvas(w = 300, h = 150) {
  const ctx = makeCtx();
  const c = { width: w, height: h, style: {}, getContext: () => ctx, addEventListener: noop };
  ctx.canvas = c;
  return c;
}

const storage = new Map();
const sandbox = {
  console, Math, Date, JSON, Map, Set, Int32Array, Float32Array, Array, Object, String, Number, Error,
  isFinite, parseInt, parseFloat, setTimeout, clearTimeout, performance,
  document: {
    createElement: (t) => (t === 'canvas' ? makeCanvas() : { style: {}, addEventListener: noop }),
    getElementById: () => makeCanvas(1440, 900),
    addEventListener: noop,
    readyState: 'complete'
  }
};
sandbox.window = sandbox;
sandbox.globalThis = sandbox;
sandbox.window.addEventListener = noop;
sandbox.window.removeEventListener = noop;
sandbox.window.requestAnimationFrame = noop;
sandbox.window.innerWidth = 1440;
sandbox.window.innerHeight = 900;
sandbox.window.devicePixelRatio = 1;
sandbox.window.localStorage = {
  getItem: (k) => (storage.has(k) ? storage.get(k) : null),
  setItem: (k, v) => storage.set(k, String(v))
};
// No AudioContext: every sound call short-circuits, exactly as in a muted tab.

const context = vm.createContext(sandbox);

const FILES = [
  'js/core/utils.js', 'js/core/input.js', 'js/core/audio.js', 'js/core/art.js', 'js/core/render.js',
  'js/world/terrain.js', 'js/world/particles.js',
  'js/entities/pickups.js', 'js/entities/projectiles.js', 'js/entities/enemies.js', 'js/entities/player.js',
  'js/systems/weapons.js', 'js/systems/upgrades.js', 'js/systems/director.js',
  'js/ui/hud.js', 'js/ui/screens.js', 'js/core/game.js'
];
for (const f of FILES) {
  vm.runInContext(fs.readFileSync(path.join(root, f), 'utf8'), context, { filename: f });
}

const VS = context.VS;
const STEP = 1 / 60;

let failures = 0;
function check(name, condition, detail) {
  if (condition) console.log(`  ok   ${name}`);
  else { failures++; console.log(`  FAIL ${name}${detail ? '  -> ' + detail : ''}`); }
}
function note(msg) { console.log(`  ..   ${msg}`); }

function tick(seconds, hold = [], draw = true) {
  const n = Math.round(seconds / STEP);
  for (let i = 0; i < n; i++) {
    for (const h of hold) VS.input.tap(h);
    VS.game.update(STEP);
    VS.input.endStep();
    for (const h of hold) VS.input.release(h);
    if (draw && i % 20 === 0) VS.game.draw(STEP);   // exercise the render path too
  }
}

/* Play for a while, taking the first offer whenever a level-up interrupts —
   otherwise a long tick stalls on the choice screen and the clock stops. */
function play(seconds, draw = false) {
  const chunk = 0.25;
  for (let t = 0; t < seconds; t += chunk) {
    if (VS.game.data.state === 'levelup') VS.game.chooseOption(0);
    tick(chunk, [], draw);
  }
  if (VS.game.data.state === 'levelup') VS.game.chooseOption(0);
}

console.log('NIGHT HARVEST smoke test');

VS.render.attach(sandbox.document.getElementById('screen'));
VS.game.init();
check('boots to the title screen', VS.game.data.state === 'title');

/* The play area must fill the window, not sit in a fixed box. */
const view = VS.render.view;
check('canvas backing store matches the window',
  VS.render.canvas.width === 1440 && VS.render.canvas.height === 900,
  `${VS.render.canvas.width}x${VS.render.canvas.height}`);
VS.game.start();
VS.game.draw(STEP);
const worldW = view.x1 - view.x0, worldH = view.y1 - view.y0;
check('the camera covers the whole window', worldW > 900 && worldH > 500,
  `${Math.round(worldW)}x${Math.round(worldH)} world units`);
sandbox.window.innerWidth = 640; sandbox.window.innerHeight = 1000;
VS.render.resize();
VS.game.draw(STEP);
check('resizing re-fits the play area',
  VS.render.canvas.width === 640 && VS.render.canvas.height === 1000 &&
  (view.x1 - view.x0) > 300,
  `${VS.render.canvas.width}x${VS.render.canvas.height}`);
sandbox.window.innerWidth = 1440; sandbox.window.innerHeight = 900;
VS.render.resize();

/* ---- auto-fire ----------------------------------------------------------- */
VS.game.resetRun();
VS.game.start();
const player = VS.player.state;
tick(3);                                     // no input at all
check('weapons fire without any input', VS.game.data.damageDealt > 0 || VS.projectiles.count() > 0,
  `${VS.projectiles.count()} projectiles, ${Math.round(VS.game.data.damageDealt)} damage`);
tick(12);
check('enemies swarm in and die', player.kills > 0, `${player.kills} kills, ${VS.enemies.count()} on field`);
check('gems drop from kills', VS.pickups.count() > 0 || player.xp > 0, `${VS.pickups.count()} gems`);

/* ---- level up and the three-way choice ----------------------------------- */
let levelled = 0;
for (let i = 0; i < 90 && VS.game.data.state === 'playing'; i++) tick(0.5);
check('experience levels the player up', player.level > 1 || VS.game.data.state === 'levelup',
  `level ${player.level}`);

VS.game.data.state = 'playing';
VS.game.data.pendingLevels = 0;
VS.game.queueLevelUp(1);
tick(0.1, [], false);
check('a level-up opens the choice screen', VS.game.data.state === 'levelup', VS.game.data.state);
check('the choice offers exactly three options', VS.game.data.options.length === 3,
  `${VS.game.data.options.length}`);
const optionNames = VS.game.data.options.map(o => `${o.name} ${o.level}`);
note('offer: ' + optionNames.join(' | '));
const beforePick = JSON.stringify(VS.weapons.owned.map(w => w.id + w.level)) + JSON.stringify(player.stats);
VS.game.chooseOption(0);
const afterPick = JSON.stringify(VS.weapons.owned.map(w => w.id + w.level)) + JSON.stringify(player.stats);
check('taking an option changes the build', beforePick !== afterPick);
check('play resumes after choosing', VS.game.data.state === 'playing', VS.game.data.state);

/* Two levels at once must present two consecutive choices, not swallow one. */
VS.game.queueLevelUp(2);
tick(0.1, [], false);
check('stacked level-ups queue up', VS.game.data.state === 'levelup' && VS.game.data.pendingLevels === 2);
VS.game.chooseOption(0);
check('the second choice opens straight after the first',
  VS.game.data.state === 'levelup' && VS.game.data.pendingLevels === 1);
VS.game.chooseOption(0);
check('the queue drains back to play', VS.game.data.state === 'playing' && VS.game.data.pendingLevels === 0);

/* Every weapon must fire and connect. Each is tested alone against a ring of
   bodies placed within reach, so a failure means that weapon, not the spawner. */
VS.game.resetRun();
VS.game.start();
for (const id of VS.weapons.ORDER) {
  VS.weapons.owned.length = 0;
  VS.weapons.clearProjectileRefs();
  VS.projectiles.clear();
  VS.enemies.clear();
  VS.player.state.stats.hp = 1e9;               // measure the weapon, not survival
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    VS.enemies.spawn('zombie', VS.player.state.x + Math.cos(a) * 70,
      VS.player.state.y + Math.sin(a) * 70, { hpMul: 40 });
  }
  const w = VS.weapons.add(id);
  w.level = VS.weapons.MAX_LEVEL;
  const before = VS.game.data.damageDealt;
  play(3);
  check(`${id} at max level fires and connects`, VS.game.data.damageDealt > before,
    `+${Math.round(VS.game.data.damageDealt - before)}`);
}

/* ---- difficulty scaling over time ---------------------------------------- */
const early = VS.director.scalingFor(30);
const late = VS.director.scalingFor(720);
check('enemy health scales hard with the clock', late.hp > early.hp * 4,
  `${early.hp.toFixed(2)} -> ${late.hp.toFixed(2)}`);
check('enemy speed scales gently', late.speed > early.speed && late.speed < early.speed * 1.6,
  `${early.speed.toFixed(2)} -> ${late.speed.toFixed(2)}`);
check('the population target grows with the clock',
  VS.director.populationTarget(600) > VS.director.populationTarget(60) * 3,
  `${VS.director.populationTarget(60)} -> ${VS.director.populationTarget(600)}`);

/* ---- the boss ------------------------------------------------------------ */
VS.game.resetRun();
VS.game.start();
VS.director.summonBoss(1);
tick(0.2, [], false);
check('a boss can take the field', !!VS.enemies.boss && VS.enemies.boss.alive);
const boss = VS.enemies.boss;
check('the boss is far tougher than the rank and file', boss.maxHp > 1000, `${boss.maxHp} hp`);
/* Killing the boss at the end of the run has to end the night, and it has to go
   through the game's own damage path so the reward handling is exercised. */
VS.game.resetRun();
VS.game.start();
VS.game.data.elapsed = VS.director.RUN_LENGTH;
VS.director.summonBoss(1);
tick(0.2, [], false);
const finalBoss = VS.enemies.boss;
check('the final boss arrives at the milestone', !!finalBoss && finalBoss.alive);
VS.game.damageEnemy(finalBoss, finalBoss.hp + 1, 0, 0, null);
tick(0.2, [], false);
check('killing the final boss wins the night', VS.game.data.state === 'victory', VS.game.data.state);

/* ---- death --------------------------------------------------------------- */
VS.game.resetRun();
VS.game.start();
player.stats.hp = 1;
player.invuln = 0;
for (let i = 0; i < 40; i++) {
  VS.enemies.spawn('zombie', player.x + 4, player.y + 4, {});
}
tick(1.2, [], false);
check('running out of health ends the run', VS.game.data.state === 'dead', VS.game.data.state);
tick(1.2, [], false);
VS.input.tap('confirm');
tick(0.1, [], false);
check('death returns to the title', VS.game.data.state === 'title', VS.game.data.state);

/* ---- performance with a full field --------------------------------------- */
VS.game.resetRun();
VS.game.start();
VS.game.data.elapsed = 600;
VS.player.state.stats.hp = 1e9;                 // measure the crowd, not the death
for (let i = 0; i < 6; i++) VS.weapons.add(VS.weapons.ORDER[i]);
for (const w of VS.weapons.owned) w.level = 6;
VS.director.swarmCircle('zombie', 200);
VS.director.swarmCircle('bat', 200);
VS.director.swarmCircle('skeleton', 200);
tick(1, [], false);
const crowd = VS.enemies.count();
const t0 = performance.now();
const frames = 120;
for (let i = 0; i < frames; i++) {
  VS.game.update(STEP);
  VS.input.endStep();
}
const perStep = (performance.now() - t0) / frames;
note(`${crowd} enemies, ${VS.projectiles.count()} projectiles: ${perStep.toFixed(2)} ms per simulation step`);
check('hundreds of enemies are on the field', crowd >= 400, `${crowd}`);
check('the simulation step stays inside a 60 Hz budget', perStep < 8,
  `${perStep.toFixed(2)} ms (budget 16.7)`);

const drawT0 = performance.now();
for (let i = 0; i < 30; i++) VS.game.draw(STEP);
const perDraw = (performance.now() - drawT0) / 30;
note(`draw pass with ${VS.enemies.count()} enemies: ${perDraw.toFixed(2)} ms (stub canvas, no rasterisation)`);
check('the draw pass does not allocate its way out of budget', perDraw < 8, `${perDraw.toFixed(2)} ms`);

/* Gems must never pile up without bound. */
for (let i = 0; i < 900; i++) VS.pickups.spawnGem(0, 0, 1);
check('gem count is capped by merging', VS.pickups.count() <= VS.pickups.pool.capacity,
  `${VS.pickups.count()} live`);

console.log(failures === 0 ? '\nAll checks passed.' : `\n${failures} check(s) failed.`);
process.exit(failures === 0 ? 0 : 1);
